import{E as e,d as t,l as n}from"./runtime-core.esm-bundler-tCF-J6l5.js";import{t as r}from"./app-HsyCwbue.js";var i=JSON.parse(`{"path":"/%E8%AF%AD%E8%A8%80/%E8%8B%B1%E8%AF%AD/Friends%E8%80%81%E5%8F%8B%E8%AE%B0/S04/S04E23.html","title":"S04E23 The One with Ross's Wedding: Part 1","lang":"zh-CN","frontmatter":{"title":"S04E23 The One with Ross's Wedding: Part 1","pageClass":"friends-page","category":["英语"],"tag":["Friends老友记"],"order":96},"git":{"createdTime":1780654155000,"updatedTime":1780654155000,"contributors":[{"name":"jackie.liu","username":"","email":"moklgy@foxmail.com","commits":1}]},"readingTime":{"minutes":63.72,"words":19117},"filePathRelative":"语言/英语/Friends老友记/S04/S04E23.md"}`),a={name:`S04E23.md`};function o(r,i,a,o,s,c){return e(),n(`div`,null,[...i[0]||=[t(`<h1 id="the-one-with-ross-s-wedding-part-1" tabindex="-1"><a class="header-anchor" href="#the-one-with-ross-s-wedding-part-1"><span>The One with Ross&#39;s Wedding: Part 1</span></a></h1><blockquote><p><em>罗斯婚礼上的那一个：第一部分</em></p></blockquote><p>The One With Ross’s Wedding Parts I and II</p><blockquote><p>有罗斯婚礼第一部分和第二部分的那个</p></blockquote><p><strong>Part I Written by:</strong> Michael Borkow</p><blockquote><p>Michael Borkow</p></blockquote><p><strong>Part II Teleplay by:</strong> Shana Goldberg-Meehan &amp; Scott Silveri</p><blockquote><p>沙娜·戈德伯格·米汉和斯科特·西尔维尼</p></blockquote><p><strong>Part II Story by:</strong> Jill Condon &amp; Amy Toomin</p><blockquote><p>吉尔·康登和艾米·图敏</p></blockquote><p><strong>Part I Transcribed by:</strong> Eric Aasen</p><blockquote><p>埃里克·艾森</p></blockquote><p><strong>Part II Transcribed by:</strong> Aaron D. Miller</p><blockquote><p>亚伦·D·米勒</p></blockquote><hr><p>🎬 <em>Chandler and Joey&#39;s, Joey and Chandler are getting ready for the flight to London and Monica comes running in.</em></p><blockquote><p>🎬 <em>钱德勒和乔伊的，乔伊和钱德勒正准备飞往伦敦的航班，莫妮卡跑了进来。</em></p></blockquote><p><strong>Monica Geller:</strong> Guys, hurry up! The flight leaves in four hours! It could take time to get a taxi! There could be traffic! The plane could leave early! When we get to London, there could be a line at customs! Come on!! (She runs back to her apartment.)</p><blockquote><p>伙计们，快点！飞机四小时后起飞！坐出租车可能需要时间！可能会有交通堵塞！飞机可以早点起飞！当我们到达伦敦时，海关可能会排起长队！来吧（她跑回公寓。）</p></blockquote><p><strong>Chandler Bing:</strong> Six-hour trip to London. That’s a lot of Monica.</p><blockquote><p>六小时的伦敦之旅。莫妮卡的话太多了。</p></blockquote><p>[Cut to the girls’ apartment, Monica is putting things into her purse as Phoebe and Rachel watch.]</p><blockquote><p>[切到女孩公寓，菲比和瑞秋看着莫妮卡把东西放进钱包。]</p></blockquote><p><strong>Monica Geller:</strong> Passport, check! (As she puts away each item, she says check.) Camera, check! Traveller’s cheques, check!</p><blockquote><p>护照，检查！（当她收起每件物品时，她说检查。）相机，检查！旅行支票，支票！</p></blockquote><p><strong>Rachel Green:</strong> Who are you saying &quot;check&quot; too?</p><blockquote><p>你说的“支票”也是谁？</p></blockquote><p><strong>Monica Geller:</strong> Myself. Y’know for remembering to pack a thing. Yeah, you do a good thing, you get a check! (pause) My mom does it, I never realized it was weird.</p><blockquote><p>我自己。你知道，记得收拾东西。是的，你做了一件好事，你得到了一张支票！（停顿）是我妈妈做的，我从没意识到这很奇怪。</p></blockquote><p><strong>Phoebe Buffay:</strong> Yeah, my mom used to put her head in the oven. Well, actually, she only did it the one time. But it was pretty weird.</p><blockquote><p>是的，我妈妈过去常把头放在烤箱里。事实上，她只做了一次。但这很奇怪。</p></blockquote><p><strong>Ross Geller:</strong> (entering) Hey!</p><blockquote><p>（进来）嘿！</p></blockquote><p><strong>Monica Geller:</strong> Hey!</p><blockquote><p>嘿！</p></blockquote><p><strong>Ross Geller:</strong> Hey! Are you ready yet?</p><blockquote><p>嘿！你准备好了吗？</p></blockquote><p><strong>Monica Geller:</strong> Yep! You got the tickets?</p><blockquote><p>是的！你拿到票了吗？</p></blockquote><p><strong>Ross Geller:</strong> Oh! Got ‘em right here, (Pats his coat pocket) check!</p><blockquote><p>哦！就在这里，（拍拍他的外套口袋）支票！</p></blockquote><p>[Cut to the guys’ apartment.]</p><blockquote><p>[转到男生公寓。]</p></blockquote><p><strong>Joey Tribbiani:</strong> It’s all London, baby! Here we go. (He takes a picture of a less than enthused Chandler and starts towards the girls’ apartment.)</p><blockquote><p>都是伦敦，宝贝！我们开始吧。（他给一个不那么热情的钱德勒拍了一张照片，然后朝女孩的公寓走去。）</p></blockquote><p><strong>Chandler Bing:</strong> You got your passport?</p><blockquote><p>你拿到护照了吗？</p></blockquote><p><strong>Joey Tribbiani:</strong> Yeah, in my third drawer on my dresser. You don’t want to lose that.</p><blockquote><p>是的，在我梳妆台的第三个抽屉里。你不想失去它。</p></blockquote><p><em>(Chandler glares at him. At first Joey doesn’t know why, it takes him a little bit to figure it out.)</em></p><blockquote><p><em>（钱德勒瞪着他。起初乔伊不知道为什么，他花了一点时间才弄明白。）</em></p></blockquote><p><strong>Joey Tribbiani:</strong> Ohh!! (Runs to his room.)</p><blockquote><p>哦！！（跑向他的房间。）</p></blockquote><p><strong>Chandler Bing:</strong> There it is.</p><blockquote><p>在那里。</p></blockquote><p>Opening Credits</p><blockquote><p>期初学分</p></blockquote><hr><p>🎬 <em>Monica and Rachel&#39;s, continued from earlier, Monica is telling Phoebe where everything is.</em></p><blockquote><p>🎬 <em>莫妮卡和瑞秋家，从早些时候开始继续，莫妮卡告诉菲比一切都在哪里。</em></p></blockquote><p><strong>Monica Geller:</strong> Okay, if you need the vacuum, it’s in my closet on the left-hand side. Ah, the garbage bags are next to the refrigerator…</p><blockquote><p>好的，如果你需要吸尘器，它在我衣橱的左手边。啊，垃圾袋在冰箱旁边…</p></blockquote><p><strong>Phoebe Buffay:</strong> Okay, okay, but Rachel’s gonna be here too, can’t I just ask her this stuff?</p><blockquote><p>好吧，好吧，但瑞秋也会在这里，我能不能问问她这件事？</p></blockquote><p><strong>Monica Geller:</strong> Yeah, okay, give that a try!</p><blockquote><p>是啊，好吧，试试看！</p></blockquote><p><strong>Chandler Bing:</strong> (entering, with Joey) All right! Let’s do it!</p><blockquote><p>（进来，和乔伊一起）好吧！让我们做吧！</p></blockquote><p><strong>Joey Tribbiani:</strong> Woo-hoo!!</p><blockquote><p>呜呼！！</p></blockquote><p><strong>Ross Geller:</strong> Yeah, cheerie-o!</p><blockquote><p>是的，干杯！</p></blockquote><p><strong>Joey Tribbiani:</strong> London baby!</p><blockquote><p>伦敦宝贝！</p></blockquote><p><strong>Chandler Bing:</strong> Okay, ‘cause that’s not gonna get annoying.</p><blockquote><p>好吧，因为这不会让人讨厌的。</p></blockquote><p><strong>Joey Tribbiani:</strong> (louder) London baby!!</p><blockquote><p>（大声点）伦敦宝贝！！</p></blockquote><p><strong>Chandler Bing:</strong> Hey, y’know what? I was wrong.</p><blockquote><p>嘿，你知道吗？我错了。</p></blockquote><p><strong>Ross Geller:</strong> Well, we’re all here! I guess we should get going!</p><blockquote><p>好吧，我们都在这里！我想我们该走了！</p></blockquote><p><strong>Phoebe Buffay:</strong> Ohhh, I wanna come over there and give you a hug and wish you luck on your wedding, but I don’t—can’t get up.</p><blockquote><p>哦，我想过来给你一个拥抱，祝你婚礼好运，但我起不来。</p></blockquote><p><strong>Ross Geller:</strong> Oh, I’ll-I’ll come hug you.</p><blockquote><p>哦，我会来拥抱你。</p></blockquote><p><strong>Phoebe Buffay:</strong> Great! Yeah, could you bring me the newspaper?</p><blockquote><p>太好了！是的，你能把报纸给我吗？</p></blockquote><p><strong>Ross Geller:</strong> Yeah. (He does so and Phoebe hugs him.)</p><blockquote><p>是的。（他这样做了，菲比拥抱了他。）</p></blockquote><p><strong>Phoebe Buffay:</strong> Oh, have a great wedding!</p><blockquote><p>哦，祝你的婚礼愉快！</p></blockquote><p><strong>Ross Geller:</strong> Thanks.</p><blockquote><p>谢谢。</p></blockquote><p><strong>Phoebe Buffay:</strong> Oh, hey, Chandler I wanna hug you too!</p><blockquote><p>哦，嘿，钱德勒，我也想拥抱你！</p></blockquote><p><strong>Chandler Bing:</strong> Hey! (Trots over)</p><blockquote><p>嘿！（小跑过去）</p></blockquote><p><strong>Phoebe Buffay:</strong> Oh, and great! You might as well bring me my book, it’s on the counter in your apartment.</p><blockquote><p>哦，太好了！你最好把我的书带来，它在你公寓的柜台上。</p></blockquote><p><strong>Chandler Bing:</strong> Oh. (Goes and gets Phoebe’s book as Rachel comes in from her room.)</p><blockquote><p>哦。（当瑞秋从她的房间进来时，她去拿菲比的书。）</p></blockquote><p><strong>Ross Geller:</strong> (to Rachel) So, we’re off.</p><blockquote><p>（对瑞秋）那么，我们走了。</p></blockquote><p><strong>Rachel Green:</strong> Have fun!</p><blockquote><p>玩得开心！</p></blockquote><p><strong>Ross Geller:</strong> Thanks! (They hug.) Ugh, I can’t believe you’re not gonna be there!</p><blockquote><p>谢谢！（他们拥抱）啊，真不敢相信你不在那里！</p></blockquote><p><strong>Rachel Green:</strong> Oh, I know.</p><blockquote><p>哦，我知道。</p></blockquote><p><strong>Ross Geller:</strong> So-so come! Why don’t you come?</p><blockquote><p>来吧！你为什么不来？</p></blockquote><p><strong>Rachel Green:</strong> What?!</p><blockquote><p>什么？！</p></blockquote><p><strong>Ross Geller:</strong> To London! Come to London. Please? It’ll mean so much to me.</p><blockquote><p>去伦敦！来伦敦吧。请这对我意义重大。</p></blockquote><p><strong>Rachel Green:</strong> Yeah, well, I gotta work, I’m sorry.</p><blockquote><p>是啊，我得工作了，对不起。</p></blockquote><p><strong>Ross Geller:</strong> Why-why can’t you take a couple of days off?</p><blockquote><p>你为什么不能休息几天？</p></blockquote><p><strong>Rachel Green:</strong> Because, I can’t! Ross, I told you, no. I can’t.</p><blockquote><p>因为，我不能！罗斯，我告诉过你，不行。</p></blockquote><p><strong>Ross Geller:</strong> This is my wedding.</p><blockquote><p>这是我的婚礼。</p></blockquote><p><strong>Monica Geller:</strong> All right, y’know what? We really are late! Let’s go! Let’s go! Let’s go!!</p><blockquote><p>好吧，你知道吗？我们真的迟到了！走吧！走吧！走吧！！</p></blockquote><p><strong>Ross Geller:</strong> Fine. You’ll-you’ll watch it on video when we get back.</p><blockquote><p>好的。我们回来的时候，你会在录像中看到的。</p></blockquote><p><strong>Chandler Bing:</strong> (entering, with Phoebe’s book.) Here you go Phoebe! Here you go Phobo! Phewbedo! Phaybobo.</p><blockquote><p>（拿着菲比的书进来。）给你菲比！给你，菲波！菲贝多！法博。</p></blockquote><p><strong>Phoebe Buffay:</strong> (laughs) Thank you.</p><blockquote><p>（笑）谢谢你。</p></blockquote><p>(Chandler kneels down with his arms spread waiting for his hug.</p><blockquote><p>（钱德勒张开双臂跪下，等待他的拥抱。</p></blockquote><p><strong>Phoebe Buffay:</strong> Thank you. (She pats him on his head.)</p><blockquote><p>谢谢。（她拍了拍他的头。）</p></blockquote><p><strong>Ross Geller:</strong> All right, let’s go! Bye, Pheebs!</p><blockquote><p>好吧，我们走吧！再见，菲比！</p></blockquote><p><strong>Joey Tribbiani:</strong> Bye, Pheebs!</p><blockquote><p>再见，菲比！</p></blockquote><p><em>(They all start out, Rachel gives each one a kiss, and says &quot;bye.&quot; In the hall, Joey says…)</em></p><blockquote><p><em>（他们都出发了，瑞秋给每个人一个吻，然后说“再见”。在大厅里，乔伊说……）</em></p></blockquote><p><strong>Joey Tribbiani:</strong> London baby!! (And Rachel slowly closes the door, sadly.)</p><blockquote><p>伦敦宝贝！！（瑞秋伤心地慢慢关上门。）</p></blockquote><p><strong>Phoebe Buffay:</strong> Oh, do you need a hug? You don’t have to bring me anything!</p><blockquote><p>哦，你需要拥抱吗？你不必给我带任何东西！</p></blockquote><p><em>(And with that, television history is made as, for the first time ever, an entire show moves it’s entire production to an entirely different country to make a single episode. We get shots of Buckingham Palace, London Bridge, Big Ben, and the London Marriott as Joey and Chandler exit.)</em></p><blockquote><p><em>（这样一来，电视史就有了新的记录，因为有史以来第一次，整个节目将其整个制作转移到一个完全不同的国家来制作一集。我们拍摄了白金汉宫、伦敦桥、大本钟以及乔伊和钱德勒离开时的伦敦万豪酒店。）</em></p></blockquote><hr><p>🎬 <em>Street in front of the London Marriott, Joey and Chandler exit. Joey is carrying a video camera and is shooting Chandler.</em></p><blockquote><p>🎬 <em>伦敦万豪酒店前的街道，乔伊和钱德勒出口。乔伊拿着摄像机正在拍摄钱德勒。</em></p></blockquote><p><strong>Joey Tribbiani:</strong> Come on! Do something!</p><blockquote><p>快点！做点什么！</p></blockquote><p><strong>Chandler Bing:</strong> I am, I’m ignoring you.</p><blockquote><p>是的，我不理你。</p></blockquote><p><strong>Joey Tribbiani:</strong> Okay, here! (Gives him the camera.) I wanna be the on camera guy. All right, first stop, Westminster Abbey. (Joey folds out his &quot;pop-up&quot; map of London. All of the major landmarks pop-up like in a pop-up book.)</p><blockquote><p>好的，在这里！（把相机给他。）我想当一名摄影师。好的，第一站，威斯敏斯特大教堂。（乔伊折叠他的“弹出式”伦敦地图。所有主要地标都像弹出式书本一样弹出。）</p></blockquote><p><strong>Chandler Bing:</strong> Oh, what the hell is that?</p><blockquote><p>哦，那到底是什么？</p></blockquote><p><strong>Joey Tribbiani:</strong> It’s London, baby! All right, the hotel’s here. (Points to the map.) Wait. No, we wanna go… No. I know. (Sets the map down.) I’m gonna have to go into the map. (So Joey literally steps into the map.)</p><blockquote><p>是伦敦，宝贝！好了，酒店就在这里。（指着地图）等等。不，我们想去……不。我知道。（放下地图）我必须进入地图。（所以乔伊真的进入地图。）</p></blockquote><p><strong>Chandler Bing:</strong> Okay, if you see a little version of me in there? Kill it!</p><blockquote><p>好吧，如果你在那里看到我的小版本？杀了它！</p></blockquote><p><strong>Joey Tribbiani:</strong> I got it! (Picks up the map and starts walking.) Here we go.</p><blockquote><p>我明白了！（拿起地图开始走。）我们走吧。</p></blockquote><p><strong>Chandler Bing:</strong> Okay. Listen-listen, we’re not gonna have to walk this way the entire time are we?</p><blockquote><p>好吧。听着，我们不必一直走这条路，是吗？</p></blockquote><p><strong>Joey Tribbiani:</strong> Shhh! (Pause) Man, you made me lose it! (He goes into the map again.)</p><blockquote><p>嘘！（停顿）老兄，你把它弄丢了！（他又进入地图。）</p></blockquote><hr><p>🎬 <em>Another street, somewhere along the River Themes, Ross, Emily, and Monica are walking to where they’re gonna get married. Emily is relating the troubles with the caterer.</em></p><blockquote><p>🎬 <em>另一条街，在Themes河沿岸的某个地方，罗斯、艾米莉和莫妮卡正走向他们要结婚的地方。艾米莉正在讲述与宴会承办人的麻烦。</em></p></blockquote><p><strong>Emily:</strong> …and that was all before 10 o’clock. The caterer rang and said it was going to be Chicken Kiev instead of Chicken Tarragon. And then the florist phoned to say there aren’t any tulips. Oh, and the chilliest has carpel-tunel syndrome. We’re not gonna be…</p><blockquote><p>……那是10点之前的事了。宴会承办人打来电话说是基辅鸡而不是龙蒿鸡。然后花店打电话说没有郁金香。哦，最冷的有心皮调音综合症。我们不会…</p></blockquote><p><strong>Ross Geller:</strong> Whoa-whoa-whoa! Emily, (Gives her the time-out signal.) honey, okay?</p><blockquote><p>哇哇！艾米丽，（给她暂停信号。）亲爱的，好吗？</p></blockquote><p><strong>Emily:</strong> Well, up yours too!</p><blockquote><p>好吧，你也来吧！</p></blockquote><p><strong>Ross Geller:</strong> What?! No! No! That’s-that’s time-out!</p><blockquote><p>什么？！不！不！那-那是暂停！</p></blockquote><p><strong>Emily:</strong> Sorry.</p><blockquote><p>对不起。</p></blockquote><p><strong>Ross Geller:</strong> Sweetie, you gotta relax. Everything’s gonna be great, okay? Come on. Come on.</p><blockquote><p>亲爱的，你要放松。一切都会好起来的，好吗？来吧，来吧。</p></blockquote><p><strong>Monica Geller:</strong> Chicken Kiev?</p><blockquote><p>基辅鸡？</p></blockquote><p><strong>Ross Geller:</strong> Um-hmm! Doesn’t that sound delicious at the last minute?</p><blockquote><p>嗯哼！在最后一刻听起来不是很好吃吗？</p></blockquote><p><strong>Monica Geller:</strong> Yeah, y’know, but something like salmon which would be so much more elegant than the chicken. And, you wouldn’t have to worry about the salmonella. (Ross pushes her.) So, I can’t wait to see this place you’re getting married!</p><blockquote><p>是的，你知道，但是像鲑鱼这样的东西会比鸡肉优雅得多。而且，你不用担心沙门氏菌。（罗斯推了推她。）所以，我迫不及待地想看看你结婚的地方！</p></blockquote><p><strong>Ross Geller:</strong> Yeah. Yeah. Yes, this place is beautiful. Emily’s parents got married here.</p><blockquote><p>是的。是的。是的，这个地方很漂亮。艾米丽的父母在这里结婚了。</p></blockquote><p><strong>Emily:</strong> I still can’t believe they’re tearing it down. It really is the most lovely building you’ll ever see. I mean it’s over… (She stops suddenly, when she sees that demolition has already started.) Oh my God!</p><blockquote><p>我还是不敢相信他们要拆掉它。这真是你见过的最可爱的建筑。我的意思是它已经结束了…（当她看到拆除已经开始时，她突然停了下来。）哦，我的天啊！</p></blockquote><p><strong>Monica Geller:</strong> It’s nice.</p><blockquote><p>很好。</p></blockquote><p><strong>Emily:</strong> Oh. Oh. (She starts running towards the building.)</p><blockquote><p>哦。哦。（她开始朝大楼跑去。）</p></blockquote><p>[Cut to inside.]</p><blockquote><p>[切到内部。]</p></blockquote><p><strong>Emily:</strong> (running in, with Ross) Oh. Oh my God. How can this be happening? What are we going to do?</p><blockquote><p>（和罗斯一起跑进来）哦，天哪，怎么会这样？我们该怎么办？</p></blockquote><p><strong>Ross Geller:</strong> It’s all right! Everything’s gonna be all right.</p><blockquote><p>没事的！一切都会好起来的。</p></blockquote><p><strong>Emily:</strong> How’s it gonna be all right?!</p><blockquote><p>怎么会没事？！</p></blockquote><p><strong>Ross Geller:</strong> Uh-huh, I see that.</p><blockquote><p>嗯，我明白了。</p></blockquote><p><strong>Monica Geller:</strong> (entering) Okay, I talked to the guy with the shovel and I found out what happened.</p><blockquote><p>（进来）好吧，我和那个拿铲子的人谈过了，我知道发生了什么事。</p></blockquote><p><strong>Ross Geller:</strong> What? What?</p><blockquote><p>什么？什么？</p></blockquote><p><strong>Monica Geller:</strong> They torn it down a few days early.</p><blockquote><p>他们提前几天把它拆了。</p></blockquote><hr><p>🎬 <em>Westminster Abbey, Joey and Chandler have successfully navigated the streets of London and are approaching the Abbey.</em></p><blockquote><p>🎬 <em>威斯敏斯特大教堂，乔伊和钱德勒已经成功地在伦敦的街道上航行，并正在接近教堂。</em></p></blockquote><p><strong>Joey Tribbiani:</strong> All right! Westminster Abbey! Hands down, best Abbey I’ve ever seen. Hey! (Pushes Chandler in front of the camera.) Okay. What do you think of the Abbey, Chandler?</p><blockquote><p>好的！威斯敏斯特大教堂！把手放下，我见过的最好的大教堂。嘿！（把钱德勒推到镜头前）好的。你觉得这座大教堂怎么样，钱德勒？</p></blockquote><p><strong>Chandler Bing:</strong> I think it’s great. It’s great. Y’know, they’re thinking of changing the name of this place.</p><blockquote><p>我觉得很好。很好。你知道，他们正在考虑改变这个地方的名字。</p></blockquote><p><strong>Joey Tribbiani:</strong> Really? To what?</p><blockquote><p>真的吗？为了什么？</p></blockquote><p><strong>Chandler Bing:</strong> To Put the Camera Away!!!</p><blockquote><p>把相机收起来！！！</p></blockquote><p><strong>Joey Tribbiani:</strong> Man, you are Westminster Crabby. (He starts chasing Chandler towards the Abbey.)</p><blockquote><p>老兄，你是威斯敏斯特暴躁的人。（他开始朝修道院追钱德勒。）</p></blockquote><hr><p>🎬 <em>Monica and Rachel&#39;s, Phoebe is trying to move off of the couch as Rachel enters.</em></p><blockquote><p>🎬 <em>莫妮卡和瑞秋家，瑞秋进来时菲比正试图离开沙发。</em></p></blockquote><p><strong>Phoebe Buffay:</strong> Oh. Oh.</p><blockquote><p>哦，哦。</p></blockquote><p><strong>Rachel Green:</strong> Oh, honey! Don’t get up! What do you need?</p><blockquote><p>哦，亲爱的！别起来！你需要什么？</p></blockquote><p><strong>Phoebe Buffay:</strong> Oh, no. Oh, nothing.</p><blockquote><p>哦，不。哦，没什么。</p></blockquote><p><strong>Rachel Green:</strong> Come on! I am here to take care of you! What do you need? Anything.</p><blockquote><p>来吧！我是来照顾你的！你需要什么？什么都行。</p></blockquote><p><strong>Phoebe Buffay:</strong> Okay, I have a wedgie.</p><blockquote><p>好的，我有一只威奇。</p></blockquote><p><strong>Rachel Green:</strong> Okay, that is all you.</p><blockquote><p>好吧，你就这些。</p></blockquote><p><strong>Phoebe Buffay:</strong> So-so, what do you want for lunch?</p><blockquote><p>那么，你午餐想吃什么？</p></blockquote><p><strong>Rachel Green:</strong> Oh, I don’t know. I guess we have to eat.</p><blockquote><p>哦，我不知道。我想我们得吃饭了。</p></blockquote><p><strong>Phoebe Buffay:</strong> Yeah, I do. What’s the matter?</p><blockquote><p>是的，我知道。怎么了？</p></blockquote><p><strong>Rachel Green:</strong> I’m just bummed about the way I left things with Ross. I shouldn’t have lied to him about having to work. He seemed so mad at me.</p><blockquote><p>我只是对我把东西留给罗斯的方式感到不安。我不该就工作的事对他撒谎。他似乎对我很生气。</p></blockquote><p><strong>Phoebe Buffay:</strong> Eh, don’t be so hard on yourself. If someone I was still in love with was getting married…</p><blockquote><p>嗯，别对自己太苛刻了。如果我还爱着的人要结婚了…</p></blockquote><p><strong>Rachel Green:</strong> (interrupting) Still in love with?!</p><blockquote><p>（打断）还爱你吗？！</p></blockquote><p><strong>Phoebe Buffay:</strong> Yeah!</p><blockquote><p>是啊！</p></blockquote><p><strong>Rachel Green:</strong> I’m not in love with Ross!</p><blockquote><p>我不爱罗斯！</p></blockquote><p><strong>Phoebe Buffay:</strong> Oh. No. No. Good! Yeah, me neither.</p><blockquote><p>哦。不。不。很好！是的，我也是。</p></blockquote><p><strong>Rachel Green:</strong> Phoebe, I’m going to Ross’s wedding because he is my ex-boyfriend and that would be really uncomfortable. Not because, I’m still in love with him! I mean, hey, y’know, I like Ross as much as the next guy, y’know? Clearly I have feelings for him, but feelings don’t mean love! I mean, I still have loving feelings for Ross. Yeah! But, I have, I have continuing feelings of love, but that doesn’t mean that-that I’m still in love with him. Y’know? I-I have sexual feelings for him, but I do love him—Ohh! Oh my God! Oh my—why didn’t you tell me?!!</p><blockquote><p>菲比，我要去罗斯的婚礼，因为他是我的前男友，那会很不舒服。不是因为，我仍然爱着他！我是说，嘿，你知道，我和下一个男人一样喜欢罗斯，你知道吗？显然我对他有感觉，但感觉并不意味着爱！我是说，我对罗斯仍然有爱的感觉。是的！但是，我有，我有持续的爱的感觉，但这并不意味着我仍然爱着他。你知道吗？我对他有性的感觉，但我确实爱他哦！哦，我的天！哦，我的天！哦，你为什么不告诉我？！！</p></blockquote><p><strong>Phoebe Buffay:</strong> We thought you knew!</p><blockquote><p>我们以为你知道！</p></blockquote><p><strong>Rachel Green:</strong> We?!</p><blockquote><p>我们？！</p></blockquote><p><strong>Phoebe Buffay:</strong> Yeah, we all know! We talk about it all the time!</p><blockquote><p>是啊，我们都知道！我们一直在谈论这个！</p></blockquote><p><strong>Rachel Green:</strong> You all know? Does Ross know?</p><blockquote><p>你们都知道吗？罗斯知道吗？</p></blockquote><p><strong>Phoebe Buffay:</strong> Oh no, Ross doesn’t know anything.</p><blockquote><p>哦，不，罗斯什么都不知道。</p></blockquote><p><strong>Rachel Green:</strong> Oh, I can not believe you didn’t tell me!</p><blockquote><p>哦，我真不敢相信你竟然不告诉我！</p></blockquote><p><strong>Phoebe Buffay:</strong> Well, because we thought you knew!! It’s so obvious! God, that would be like telling Monica, &quot;Hey, you like things clean.&quot;</p><blockquote><p>嗯，因为我们以为你知道！！太明显了！天啊，那就像告诉莫妮卡，“嘿，你喜欢干净的东西。”</p></blockquote><hr><p>🎬 <em>A park in London, Joey and Chandler walk up to a souvenir stand.</em></p><blockquote><p>🎬 <em>伦敦的一个公园，乔伊和钱德勒走向一个纪念品摊。</em></p></blockquote><p><strong>Joey Tribbiani:</strong> Hey!</p><blockquote><p>嘿！</p></blockquote><p><strong>The Vendor:</strong> So, what are you guys in the market for? We’ve got uh, scarves, tulip post cards...</p><blockquote><p>那个么，你们来市场干什么？我们有围巾、郁金香明信片。。。</p></blockquote><p><strong>Joey Tribbiani:</strong> Check this out? Huh? (Joey has this big tall hat with a British flag on the front of it.) Yeah. That’s the stuff. What do you think?</p><blockquote><p>看看这个？哈？（乔伊有一顶大而高的帽子，前面有一面英国国旗。）是的。就是这些东西。你觉得怎么样？</p></blockquote><p><strong>Chandler Bing:</strong> Well, I don’t have to buy that, &quot;I’m with stupid&quot; T-shirt anymore.</p><blockquote><p>嗯，我再也不用买那件“我和傻瓜在一起”的t恤了。</p></blockquote><p><strong>Joey Tribbiani:</strong> Well, I like it. Here you go. (He pays for the hat.)</p><blockquote><p>嗯，我喜欢。给你。（他付帽子的钱。）</p></blockquote><p><strong>Chandler Bing:</strong> All right, look, you’re not really gonna buy that are you? Don’t you think you’ve embarrassed me enough for one day?</p><blockquote><p>好吧，听着，你不是真的要买吗？你不觉得你让我难堪了一天吗？</p></blockquote><p><strong>Joey Tribbiani:</strong> Oh, I embarrass you?</p><blockquote><p>哦，我让你难堪了？</p></blockquote><p><strong>Chandler Bing:</strong> How can I answer that when I’m pretending I don’t know you?</p><blockquote><p>当我假装不认识你的时候，我怎么回答？</p></blockquote><p><strong>The Vendor:</strong> He’s just jealous. You’ll fit right in; all Londoners wear them!</p><blockquote><p>他只是嫉妒。你会很合身的，所有的伦敦人都穿！</p></blockquote><p><strong>Chandler Bing:</strong> Oh really? Then how come no one here is wearing them?</p><blockquote><p>哦，真的吗？那为什么这里没有人穿呢？</p></blockquote><p><strong>The Vendor:</strong> (looks around) They’re all tourists.</p><blockquote><p>（环顾四周）他们都是游客。</p></blockquote><p><strong>Chandler Bing:</strong> All right, look, if you insist on wearing that, in public, y’know, you’re gonna spend the rest of the afternoon all by yourself.</p><blockquote><p>好吧，听着，如果你坚持穿这个，在公共场合，你知道，你会一个人度过下午的剩余时间。</p></blockquote><p><strong>Joey Tribbiani:</strong> Oh yeah? (Puts the hat on.) If you’re gonna make me choose between you and the hat? I choose the hat.</p><blockquote><p>哦，是吗？（戴上帽子）如果你想让我在你和帽子之间选择的话？我选择帽子。</p></blockquote><p><strong>The Vendor:</strong> Good choice.</p><blockquote><p>不错的选择。</p></blockquote><p><strong>Joey Tribbiani:</strong> Thanks.</p><blockquote><p>谢谢。</p></blockquote><p><strong>Chandler Bing:</strong> Okay, wait. All right, that’s it, okay, I’m out of here. I am not going to be embarrassed anymore! (He trips over a box, falls into a flower stand and walks away trying to be cool.)</p><blockquote><p>好吧，等等。好吧，就这样，好吧，我要离开这里。我不会再感到尴尬了！（他被一个盒子绊倒，掉进花架，然后走开，试图保持冷静。）</p></blockquote><hr><p>🎬 <em>The hotel, Ross’s room, Emily is entering.</em></p><blockquote><p>🎬 <em>酒店，罗斯的房间，艾米丽正在进入。</em></p></blockquote><p><strong>Emily:</strong> Hello?</p><blockquote><p>喂？</p></blockquote><p><strong>Ross Geller:</strong> Hey! I just spoke to your dad, and you know what? He seems to think we’ll be able to find a new place for the wedding.</p><blockquote><p>嘿！我刚和你爸爸谈过，你知道吗？他似乎认为我们能为婚礼找到一个新地方。</p></blockquote><p><strong>Emily:</strong> We don’t have to.</p><blockquote><p>我们不必。</p></blockquote><p><strong>Ross Geller:</strong> Whoa-whoa-what? You found a place?</p><blockquote><p>哇哇什么？你找到地方了？</p></blockquote><p><strong>Emily:</strong> No. But, Monica and I were talking, and-and I was so upset about the hall being knocked down, and she suggested that we put the wedding off for a bit.</p><blockquote><p>没有。但是，莫妮卡和我在聊天，我对大厅被撞倒感到非常不安，她建议我们把婚礼推迟一点。</p></blockquote><p><strong>Ross Geller:</strong> She said what?</p><blockquote><p>她说什么？</p></blockquote><p><strong>Emily:</strong> She said, &quot;If I’m not gonna be happy getting married somewhere that we find in a day, well then we should just postpone it.&quot;</p><blockquote><p>她说，“如果我在一天之内找不到结婚的地方，那我们就推迟结婚。”</p></blockquote><p><strong>Ross Geller:</strong> Postpone it? Emily, do you think Monica realises how much our parents spent on this wedding? Do you my sister’s teeny-tiny little brain comprehends that people took time out of their lives to fly thousands of miles to be here, huh? (He puts his pants on backwards.) This isn’t right.</p><blockquote><p>推迟？艾米丽，你认为莫妮卡知道我们的父母在婚礼上花了多少钱吗？你知道吗？我妹妹小小的大脑知道人们花时间飞几千英里来这里，是吗？（他把裤子穿反了。）这不对。</p></blockquote><p><strong>Emily:</strong> I realize that people are going to be disappointed. But, I’m sure they’ll come back when we can do it right.</p><blockquote><p>我知道人们会失望的。但是，我相信当我们做对的时候，他们会回来的。</p></blockquote><p><strong>Ross Geller:</strong> I can’t ask people to do that? Would you ask people to do that? (Holds out his pants)</p><blockquote><p>我不能让别人那样做？你会让别人那样做吗？（伸出他的裤子）</p></blockquote><p><strong>Emily:</strong> Don’t you point your pants at me! (She throws them on the floor.) We have no choice! Anywhere that’s half-decent would’ve be booked months ago, Ross don’t you understand? This is our wedding I’m talking about.</p><blockquote><p>别把你的裤子指着我！（她把裤子扔到地板上。）我们别无选择！任何半体面的地方都会在几个月前被预订的，罗斯，你不明白吗？我说的是我们的婚礼。</p></blockquote><p><strong>Ross Geller:</strong> The only thing I understand is; postponing it is not an option. This is when we’re getting married.</p><blockquote><p>我唯一能理解的是，推迟是不行的。这是我们结婚的时候。</p></blockquote><p><strong>Emily:</strong> So what are you saying? It’s now or never?</p><blockquote><p>那你在说什么？是现在还是永远？</p></blockquote><p><strong>Ross Geller:</strong> No. I’m saying it’s now. (He starts putting on his pants, backwards again.)</p><blockquote><p>不。我是说现在。（他开始穿裤子，又向后穿。）</p></blockquote><p><strong>Emily:</strong> Or?</p><blockquote><p>还是？</p></blockquote><p><strong>Ross Geller:</strong> There’s no ‘or’ in mind. What is wrong with these pants?!!</p><blockquote><p>没有“或”的意思。这条裤子怎么了？！！</p></blockquote><p><strong>Emily:</strong> It’s not the pants. It’s you that is backwards. And if, and if you don’t understand how important this is to me, well then, perhaps we shouldn’t get married at all! (She storms out.)</p><blockquote><p>不是裤子。是你在倒退。如果，如果你不明白这对我有多重要，那么，也许我们根本不应该结婚！（她怒气冲冲地走了。）</p></blockquote><p><strong>Ross Geller:</strong> (chasing her, trying to zip up his pants. His got them on right now.) No, wait! Emily! No, wait, stop! Emily, please—(He catches something important in the zipper and howls like a little boy and falls to the floor.)</p><blockquote><p>（追着她，试着拉上裤子的拉链。他的裤子现在就穿上了。）不，等等！艾米丽！不，等等，停！艾米丽，求你了-（他在拉链里抓了个重要的东西，像个小男孩一样嚎叫，然后摔倒在地。）</p></blockquote><p>Commercial Break</p><blockquote><p>商业休息</p></blockquote><hr><p>🎬 <em>Monica and Rachel&#39;s, Phoebe is on the couch as Rachel returns carrying a bunch of shopping bags.</em></p><blockquote><p>🎬 <em>莫妮卡和瑞秋家，菲比坐在沙发上，瑞秋拿着一堆购物袋回来。</em></p></blockquote><p><strong>Phoebe Buffay:</strong> Hey!</p><blockquote><p>嘿！</p></blockquote><p><strong>Rachel Green:</strong> (depressed) Hi.</p><blockquote><p>（沮丧地）嗨。</p></blockquote><p><strong>Phoebe Buffay:</strong> So, did shopping make you feel any better about Ross?</p><blockquote><p>那么，购物让你对罗斯感觉好点了吗？</p></blockquote><p><strong>Rachel Green:</strong> Manhattan does not have enough stores.</p><blockquote><p>曼哈顿没有足够的商店。</p></blockquote><p><strong>Phoebe Buffay:</strong> Well, I think I can help you get over him.</p><blockquote><p>嗯，我想我可以帮你忘掉他。</p></blockquote><p><strong>Rachel Green:</strong> You can?</p><blockquote><p>你能吗？</p></blockquote><p><strong>Phoebe Buffay:</strong> Yeah. I just need you to bring me some photos of Ross.</p><blockquote><p>是的。我只需要你给我带些罗斯的照片。</p></blockquote><p><strong>Rachel Green:</strong> Um-hmm.</p><blockquote><p>嗯。</p></blockquote><p><strong>Phoebe Buffay:</strong> And a small piece of chocolate.</p><blockquote><p>还有一小块巧克力。</p></blockquote><p><strong>Rachel Green:</strong> Okay.</p><blockquote><p>好的。</p></blockquote><p><strong>Phoebe Buffay:</strong> And a glass of tepid water. (She gathers up all of these things.)</p><blockquote><p>还有一杯温水。（她收集了所有这些东西。）</p></blockquote><p><strong>Rachel Green:</strong> Ooh, is this one of those things where you throw it in a bag with some graveyard dirt and hang it from a north-facing tree?</p><blockquote><p>哦，这是你把它和墓地的泥土一起放在袋子里，然后挂在朝北的树上的那种东西吗？</p></blockquote><p><strong>Phoebe Buffay:</strong> Uh, only if you have the hiccups too. Yeah, the pictures are for you, the water and the chocolate is for me. I just didn’t feel like getting up. Okay, I’m gonna show you a picture of Ross. Okay? And you’re going to remember all of the bad things about him. All right? Really focus on his flaws.</p><blockquote><p>嗯，除非你也打嗝。是的，照片是给你的，水和巧克力是给我的。我只是不想起床。好吧，我给你看一张罗斯的照片。好吗？你会记得他所有的坏处。好吗？真的关注他的缺点。</p></blockquote><p><strong>Rachel Green:</strong> I can do that. I certainly did it when we were going out.</p><blockquote><p>我能做到。我们出去的时候我当然做到了。</p></blockquote><p><strong>Phoebe Buffay:</strong> Okay. Umm, before we get started, I just wanna say for the record that I love Ross, I think he’s such a great guy. Here. (Hands her the picture, Rachel grabs it out of her hand.) Okay, now, close your eyes. And imagine that you’re with Ross okay and imagine that you’re kissing him. And you’re-you’re running your hands all over his body. And then you run your hands through his hair, but eew-oh gross it’s some kind of grease, it’s—uck! Hah?</p><blockquote><p>好吧。嗯，在我们开始之前，我只想说我爱罗斯，我觉得他是个很棒的人。给。（把照片递给她，瑞秋从手中接过。）好吧，现在，闭上你的眼睛。想象你和罗斯在一起好吧，想象你在吻他。然后你用手抚摸他的全身。然后你用手抚摸他的头发，但哇哦，恶心，这是一种油脂，真该死！哈？</p></blockquote><p><strong>Rachel Green:</strong> I don’t know, his uh, his hair never really bothered me that much, and y’know it was always more crunchy than it was greasy.</p><blockquote><p>我不知道，他的头发从来没有让我那么烦恼过，而且你知道它总是比油腻的更脆。</p></blockquote><p><strong>Phoebe Buffay:</strong> Okay, this is going to be harder than I thought. Umm, let’s try some uh, aversion therapy.</p><blockquote><p>好吧，这比我想象的要难。嗯，让我们试试，呃，厌恶疗法。</p></blockquote><p><strong>Rachel Green:</strong> Okay.</p><blockquote><p>好的。</p></blockquote><p><strong>Phoebe Buffay:</strong> Okay?</p><blockquote><p>好吗？</p></blockquote><p><strong>Rachel Green:</strong> All right.</p><blockquote><p>好的。</p></blockquote><p><strong>Phoebe Buffay:</strong> So uh, now look at the picture…</p><blockquote><p>那么，嗯，现在看看这张照片…</p></blockquote><p><strong>Rachel Green:</strong> Okay.</p><blockquote><p>好的。</p></blockquote><p><strong>Phoebe Buffay:</strong> All right, and umm… (She grabs the picture and smacks her in the head.)</p><blockquote><p>好吧，嗯…（她抓起照片，拍了拍她的头。）</p></blockquote><p><strong>Rachel Green:</strong> Ow!</p><blockquote><p>哦！</p></blockquote><p><strong>Phoebe Buffay:</strong> Okay, how do you feel now?</p><blockquote><p>好吧，你现在感觉怎么样？</p></blockquote><p><strong>Rachel Green:</strong> Well, I like you less!</p><blockquote><p>嗯，我不太喜欢你了！</p></blockquote><hr><p>🎬 <em>Chandler and Joey’s hotel room. Chandler is watching TV as Joey returns, still wearing his hat.</em></p><blockquote><p>🎬 <em>钱德勒和乔伊的酒店房间。乔伊回来时钱德勒正在看电视，乔伊还戴着帽子。</em></p></blockquote><p><strong>Joey Tribbiani:</strong> Hey.</p><blockquote><p>嘿。</p></blockquote><p><strong>Chandler Bing:</strong> Hey. (He nods at the hat.)</p><blockquote><p>嘿。（他朝帽子点头。）</p></blockquote><p><strong>Joey Tribbiani:</strong> Oh. (Takes off the hat.) Sorry!</p><blockquote><p>哦。（摘下帽子）对不起！</p></blockquote><p><strong>Chandler Bing:</strong> No-no-no, y’know what? I really shouldn’t have said that you were embarrassing me, I mean that really wasn’t cool. And if it makes you feel any better, I’ve had a really lousy day.</p><blockquote><p>不，不，你知道吗？我真的不该说你让我难堪，我是说那真的不酷。如果这能让你感觉好一点的话，我今天过得真的很糟糕。</p></blockquote><p><strong>Joey Tribbiani:</strong> Me too.</p><blockquote><p>我也是。</p></blockquote><p><strong>Chandler Bing:</strong> Yeah?</p><blockquote><p>是吗？</p></blockquote><p><strong>Joey Tribbiani:</strong> Noo!! I’ve had the best day ever! Dude, check this out!</p><blockquote><p>不！！我度过了有史以来最好的一天！哥们，看看这个！</p></blockquote><p><strong>Monica Geller:</strong> (entering) Hey!</p><blockquote><p>（进来）嘿！</p></blockquote><p><strong>Joey Tribbiani:</strong> Sh-shh-shh! (He motions for her to watch something he has taped.)</p><blockquote><p>嘘嘘！（他示意她看他录的东西。）</p></blockquote><p>[Cut to the tape Joey made in front of some famous place in London with a rather famous English-type person.]</p><blockquote><p>[切到乔伊在伦敦某个著名的地方和一个相当有名的英国人在一起的录像带。]</p></blockquote><p><strong>Joey Tribbiani:</strong> (on tape) Okay, so say hi to my friend and tell him that you like the hat.</p><blockquote><p>（录音）好的，跟我朋友打个招呼，告诉他你喜欢这顶帽子。</p></blockquote><p><strong>Fergie:</strong> (Yep, Sarah, the Duchess of York) Okay, so umm, what’s your friend’s name?</p><blockquote><p>（是的，莎拉，约克公爵夫人）好的，那么，嗯，你朋友叫什么名字？</p></blockquote><p><strong>Joey Tribbiani:</strong> (on tape) Oh, Chandler.</p><blockquote><p>（录音）哦，钱德勒。</p></blockquote><p><strong>Fergie:</strong> Hi Chandler! (Waves)</p><blockquote><p>嗨，钱德勒！（挥手）</p></blockquote><p><strong>Chandler Bing:</strong> That’s… That’s was…</p><blockquote><p>那是…那是…</p></blockquote><p><strong>Monica Geller:</strong> Oh my God!</p><blockquote><p>哦，我的天啊！</p></blockquote><p><strong>Joey Tribbiani:</strong> That’s Fergie baby!!</p><blockquote><p>那是菲姬宝贝！！</p></blockquote><p><strong>Fergie:</strong> Joey says you don’t really like his hat, but I think it’s kinda dashing.</p><blockquote><p>乔伊说你不太喜欢他的帽子，但我觉得有点时髦。</p></blockquote><p><strong>Chandler Bing:</strong> How did you? How? How?</p><blockquote><p>你怎么做到的？怎么做到的？怎么做到的？</p></blockquote><p><strong>Joey Tribbiani:</strong> Well, I was trying to figure out how to get to Buckingham Palace, right? So, I’m in my map and-and…(Ross enters) Hey!</p><blockquote><p>嗯，我想知道怎么去白金汉宫，对吗？所以，我在我的地图上并且…（罗斯进来）嘿！</p></blockquote><p><strong>Monica Geller:</strong> Hey!</p><blockquote><p>嘿！</p></blockquote><p><strong>Ross Geller:</strong> Hi. I understand you had a little talk with Emily.</p><blockquote><p>嗨，我知道你和艾米丽谈过了。</p></blockquote><p><strong>Monica Geller:</strong> (laughs) Yes, I did! And you are welcome!</p><blockquote><p>（笑）是的，我做到了！不客气！</p></blockquote><p><strong>Ross Geller:</strong> Am I?! And was it your idea to postpone the wedding?!</p><blockquote><p>是我吗？！婚礼延期是你的主意吗？！</p></blockquote><p><strong>Monica Geller:</strong> Umm…</p><blockquote><p>嗯…</p></blockquote><p><strong>Chandler Bing:</strong> I’m gonna go to the bathroom.</p><blockquote><p>我要去洗手间。</p></blockquote><p><strong>Joey Tribbiani:</strong> Wait up! (They both run to the bathroom.)</p><blockquote><p>等等！（他们都跑到浴室。）</p></blockquote><p><strong>Ross Geller:</strong> Hey-hey, since you’re the ‘fix-it’ lady, here’s a pickle, what do you do when the bride says she doesn’t want to have the wedding at all?</p><blockquote><p>嘿，嘿，既然你是“修好”的女士，这里有个问题，当新娘说她根本不想举行婚礼时，你怎么办？</p></blockquote><p><strong>Monica Geller:</strong> She said that?!</p><blockquote><p>她说的？！</p></blockquote><p><strong>Ross Geller:</strong> Yeah.</p><blockquote><p>是的。</p></blockquote><p><strong>Monica Geller:</strong> Why?!</p><blockquote><p>为什么？！</p></blockquote><p><strong>Ross Geller:</strong> I don’t know, I told her it was stupid to put off the wedding just because the hall was gone and she liked flipped out.</p><blockquote><p>我不知道，我告诉她推迟婚礼是愚蠢的，因为大厅不见了，她喜欢发疯。</p></blockquote><p><strong>Monica Geller:</strong> Oh my God. You’re even dumber than I am!</p><blockquote><p>哦，我的天啊。你比我还笨！</p></blockquote><p><strong>Ross Geller:</strong> Excuse me?</p><blockquote><p>劳驾？</p></blockquote><p><strong>Monica Geller:</strong> Ross, how long have you been planning this wedding?</p><blockquote><p>罗斯，你计划这场婚礼有多久了？</p></blockquote><p><strong>Ross Geller:</strong> I don’t know. A month?</p><blockquote><p>我不知道。一个月？</p></blockquote><p><strong>Monica Geller:</strong> Emily has probably been planning it since she was five! Ever since the first time she took a pillowcase and hung it off the back of her head. That’s what we did! We dreamed about the perfect wedding, and the perfect place, with the perfect four-tiered wedding cake (Starting to cry), with the little people on top. (Ross gets thrown a box of Kleenex from the bathroom and he gives her one.) Thanks. But the most important part is that we had the perfect guy who understood just how important all that other stuff was.</p><blockquote><p>艾米丽可能从五岁起就开始计划了！自从她第一次拿枕头套挂在脑后。我们就是这么做的！我们梦想着完美的婚礼，完美的地方，完美的四层婚礼蛋糕（开始哭泣），上面有小人物。（罗斯从浴室里扔出一盒纸巾，他给了她一盒。）谢谢。但最重要的是，我们有一个完美的男人，他知道所有其他东西是多么重要。</p></blockquote><p><strong>Ross Geller:</strong> I had no idea. And that-that pillowcase thing, I thought you guys were just doing the flying nun.</p><blockquote><p>我不知道。那个枕套的事，我还以为你们只是在演飞行修女呢。</p></blockquote><p><strong>Monica Geller:</strong> Sometimes we were.</p><blockquote><p>有时候我们是。</p></blockquote><p><strong>Ross Geller:</strong> Come on. You gotta help me figure out what to do. Okay?</p><blockquote><p>来吧，你得帮我想想怎么做，好吗？</p></blockquote><p><strong>Monica Geller:</strong> Okay.</p><blockquote><p>好的。</p></blockquote><p><strong>Ross Geller:</strong> Come on. (They leave and Chandler sticks his head out.)</p><blockquote><p>来吧。（他们走了，钱德勒把头伸出来。）</p></blockquote><p><strong>Chandler Bing:</strong> That was pretty intense huh?</p><blockquote><p>那很紧张，是吗？</p></blockquote><p><strong>Joey Tribbiani:</strong> Yeah. (Pause) Hey, I hope Ross didn’t think that we just went in there because we were uncomfortable being out here!</p><blockquote><p>是的。（停顿）嘿，我希望罗斯没想到我们只是进去了，因为我们在这里不舒服！</p></blockquote><p><strong>Chandler Bing:</strong> (glares at him) I hope he did!</p><blockquote><p>（怒视着他）我希望他做到了！</p></blockquote><hr><p>🎬 <em>Monica and Rachel&#39;s, the phone rings and Phoebe answers it.</em></p><blockquote><p>🎬 <em>莫妮卡和瑞秋家，电话铃响了，菲比接了电话。</em></p></blockquote><p><strong>Phoebe Buffay:</strong> Hello.</p><blockquote><p>你好。</p></blockquote><p><strong>Joey Tribbiani:</strong> (on phone) Hey, Pheebs! It’s Joey!</p><blockquote><p>（在电话里）嘿，菲比！是乔伊！</p></blockquote><p><strong>Phoebe Buffay:</strong> Hey, Joey! Hey! Ooh! Ooh! I just say someone on the—that looks just like you on the subway. And I was gonna go over and say ‘hi!’ but then I figured, he doesn’t care if he looks like you.</p><blockquote><p>嘿，乔伊！嘿！哦！哦！我只是说地铁里有人长得像你。我本来想过去打声招呼的！但后来我想，他不在乎他长得像你。</p></blockquote><p><strong>Joey Tribbiani:</strong> That just cost me four bucks. But uh listen, I just called to see how the chick and the duck are doing?</p><blockquote><p>那只花了我四块钱。但是，呃，听着，我只是打电话来看看小鸡和小鸭怎么样了？</p></blockquote><p><strong>Phoebe Buffay:</strong> Ohh, they’re having a great time with their Aunt Phoebe! Aunt Rachel hasn’t been helpful at all. So, do you miss me?</p><blockquote><p>哦，他们和菲比阿姨在一起玩得很开心！瑞秋阿姨一点帮助都没有。那么，你想我吗？</p></blockquote><p><strong>Joey Tribbiani:</strong> Kinda, but I’ve just been having way too much fun.</p><blockquote><p>有点，但我只是玩得太开心了。</p></blockquote><p><strong>Phoebe Buffay:</strong> So you’re not homesick yet?</p><blockquote><p>你还没有想家？</p></blockquote><p><strong>Joey Tribbiani:</strong> No, I don’t think so.</p><blockquote><p>不，我不这么认为。</p></blockquote><p><strong>Phoebe Buffay:</strong> All right, the seven of us miss you.</p><blockquote><p>好吧，我们七个人都很想你。</p></blockquote><p><strong>Joey Tribbiani:</strong> Who’s seven?</p><blockquote><p>谁七岁？</p></blockquote><p><strong>Phoebe Buffay:</strong> Y’know, me, Rachel, the birds, the babies…</p><blockquote><p>你知道，我，瑞秋，那些鸟，那些婴儿…</p></blockquote><p><strong>Joey Tribbiani:</strong> Ahh, the babies miss me?</p><blockquote><p>啊，孩子们想我了？</p></blockquote><p><em>(There is a knock on Rachel and Phoebe’s door.)</em></p><blockquote><p><em>（有人敲瑞秋和菲比的门。）</em></p></blockquote><p><strong>Phoebe Buffay:</strong> Ooh, the pizza guy’s here!</p><blockquote><p>哦，披萨店的家伙来了！</p></blockquote><p><strong>Joey Tribbiani:</strong> What? You ordered pizza without me?!</p><blockquote><p>什么？你没有我就点了披萨？！</p></blockquote><p><strong>Phoebe Buffay:</strong> Yeah. But y’know we were thinking about you, y’know we ordered the Joey Special.</p><blockquote><p>是啊。但是你知道我们在想你，你知道我们点了乔伊特餐。</p></blockquote><p><strong>Joey Tribbiani:</strong> Two pizzas?!</p><blockquote><p>两个比萨饼？！</p></blockquote><p><strong>Phoebe Buffay:</strong> Yep! Okay, gotta go, talk to you later.</p><blockquote><p>是的！好了，我得走了，待会儿再谈。</p></blockquote><p><strong>Joey Tribbiani:</strong> Wait, well, where did you get it from?!</p><blockquote><p>等等，你从哪里弄来的？！</p></blockquote><p><em>(Phoebe has already hung up, leaving Joey in the dark. So Joey decides to watch some TV and turns on a rerun of Cheers, with the theme song playing. At first, he’s happy, but as the song progresses Joey gets depressed and homesick.)</em></p><blockquote><p><em>（菲比已经挂断了电话，把乔伊留在了黑暗中。所以乔伊决定看一些电视，打开一个欢呼的重播，播放主题曲。起初，他很高兴，但随着歌曲的发展，乔伊变得沮丧和想家。）</em></p></blockquote><hr><p>🎬 <em>Ross and Emily’s planned wedding place, Monica is dragging Emily in.</em></p><blockquote><p>🎬 <em>罗斯和艾米丽计划的婚礼地点，莫妮卡正把艾米丽拖进来。</em></p></blockquote><p><strong>Emily:</strong> Monica, why have you brought me here of all places?!</p><blockquote><p>莫妮卡，你为什么把我带到这里来？！</p></blockquote><p><strong>Monica Geller:</strong> You’ll see.</p><blockquote><p>你会明白的。</p></blockquote><p><strong>Emily:</strong> I tell you, this wedding is not going to happen.</p><blockquote><p>我告诉你，这场婚礼不会举行的。</p></blockquote><p><em>(At that Ross plugs in some Christmas lights to light the place up.)</em></p><blockquote><p><em>（这时罗斯插上了一些圣诞灯，照亮了整个地方。）</em></p></blockquote><p><strong>Emily:</strong> Oh God.</p><blockquote><p>哦，天啊。</p></blockquote><p><strong>Ross Geller:</strong> Okay? But-but imagine a lot more lights, okay? And-and y’know fewer bricks, and-and-and flowers, and candles…</p><blockquote><p>好吗？但是想象更多的灯光，好吗？而且你知道的砖头、花和蜡烛都少了…</p></blockquote><p><strong>Monica Geller:</strong> And the musicians, look, they can go over here (Points to a little alcove), okay? And the chairs can face this way (Points), and… (Points to Ross) You go.</p><blockquote><p>音乐家们，看，他们可以到这里（指向一个小壁龛），好吗？椅子可以朝这边（指着），然后…（指着罗斯）你走。</p></blockquote><p><strong>Ross Geller:</strong> But-but, if you don’t love this, we’ll do it in any other place at any other time. Really, it’s fine, whatever you want.</p><blockquote><p>但是，如果你不喜欢这个，我们会在任何时间在任何其他地方做。真的，没关系，你要什么都行。</p></blockquote><p><strong>Emily:</strong> It’s perfect.</p><blockquote><p>太完美了。</p></blockquote><p><strong>Ross Geller:</strong> And, I don’t know, if it starts to rain…</p><blockquote><p>而且，我不知道，如果开始下雨…</p></blockquote><p><strong>Emily:</strong> Well then we’ll get wet. (They kiss.)</p><blockquote><p>那我们就淋湿了。（他们接吻。）</p></blockquote><p><strong>Monica Geller:</strong> Ohh. And I don’t even have a date.</p><blockquote><p>哦。我甚至没有约会。</p></blockquote><hr><p>🎬 <em>Monica and Rachel&#39;s, Rachel is in her bedroom.</em></p><blockquote><p>🎬 <em>莫妮卡和瑞秋的，瑞秋在她的卧室。</em></p></blockquote><p><strong>Rachel Green:</strong> Pheebs?</p><blockquote><p>菲比？</p></blockquote><p><strong>Phoebe Buffay:</strong> Yeah?</p><blockquote><p>是吗？</p></blockquote><p><strong>Rachel Green:</strong> Do you remember where the duck food is?</p><blockquote><p>你记得鸭子的食物在哪里吗？</p></blockquote><p><strong>Phoebe Buffay:</strong> Yeah, it’s in the guys’ apartment under the sink. Why?</p><blockquote><p>是的，在男人的公寓水槽下面。为什么？</p></blockquote><p><strong>Rachel Green:</strong> (enters with a bag packed) Because I’m going to London.</p><blockquote><p>（带着包进来）因为我要去伦敦。</p></blockquote><p><strong>Phoebe Buffay:</strong> What?! What do you mean you’re going to London?</p><blockquote><p>什么？！你去伦敦是什么意思？</p></blockquote><p><strong>Rachel Green:</strong> Yeah, I have to tell Ross that I love him. Now honey, you take care, you don’t have those babies until I get back. (Kisses her stomach.)</p><blockquote><p>是啊，我得告诉罗斯我爱他。亲爱的，你保重，在我回来之前你不能生孩子。（吻了吻她的肚子。）</p></blockquote><p><strong>Phoebe Buffay:</strong> I—Rachel, you can’t go! Ross loves Emily!</p><blockquote><p>我，瑞秋，你不能去！罗斯爱艾米丽！</p></blockquote><p><strong>Rachel Green:</strong> Yeah, I know, I know, I know he does. But I have to tell him how I feel! He deserves to have all the information and then he can make an informed decision.</p><blockquote><p>是的，我知道，我知道，我知道他知道。但我必须告诉他我的感受！他应该得到所有的信息，然后才能做出明智的决定。</p></blockquote><p><strong>Phoebe Buffay:</strong> That’s not why you’re going! You’re going because you hope he’s gonna say, &quot;Yeah, I love you too, Rach. Forget that British chippy.&quot;</p><blockquote><p>这不是你要去的原因！你去是因为你希望他会说，“是的，我也爱你，瑞秋。忘了那个英国小鬼吧。”</p></blockquote><p><strong>Rachel Green:</strong> Ohh—Do you think he will?!</p><blockquote><p>哦，你认为他会吗？！</p></blockquote><p><strong>Phoebe Buffay:</strong> No! Because he’s in love with the British chippy! Look, Rachel, if you go, you’re just gonna mess with his head and ruin his wedding! Y’know, it’s too late! You missed you’re chance! I’m sorry, I know this must be really hard, it’s over.</p><blockquote><p>不！因为他爱上了英国的奇比！听着，瑞秋，如果你走了，你只会弄乱他的脑袋，毁掉他的婚礼！你知道，太晚了！你错过了机会！对不起，我知道这一定很难，结束了。</p></blockquote><p><strong>Rachel Green:</strong> Y’know what? No. It’s not over until someone says, &quot;I do.&quot; (Exits)</p><blockquote><p>你知道吗？不，直到有人说“我愿意”，一切才结束</p></blockquote><p><strong>Phoebe Buffay:</strong> I do! I do! I do! (Chases her into the hall, but Rachel doesn’t stop.) I do! (Gives up.) Ugh, like I can really chase you. I’m carrying a litter.</p><blockquote><p>我知道！我愿意！我愿意！（追着她进了大厅，但瑞秋没有停下来。）我停下来了！（放弃）啊，好像我真的能追上你。我带着一个垃圾。</p></blockquote><p>Commercial Break</p><blockquote><p>商业休息</p></blockquote><hr><p>🎬 <em>Moving Shot towards The Waltham House. A phone is ringing.</em></p><blockquote><p>🎬 <em>向沃尔瑟姆家移动的镜头。电话铃响了。</em></p></blockquote><p><strong>Housekeeper:</strong> The Waltham Residence.</p><blockquote><p>沃尔瑟姆公寓。</p></blockquote><p><strong>Phoebe Buffay:</strong> Oh...yes..is this..umm..Emily’s Parents’ house.</p><blockquote><p>哦……是的……这是……嗯……艾米丽父母的房子。</p></blockquote><p><strong>Housekeeper:</strong> This is the housekeeper speaking. And by the way, young lady, that is not how one addresses oneself on the telephone. First one identifies oneself and then asks for the person with whom one wishes to speak.</p><blockquote><p>我是管家。顺便说一句，年轻的女士，在电话里不是这样称呼自己的。首先，一个人表明自己的身份，然后要求与之交谈的人。</p></blockquote><p><strong>Phoebe Buffay:</strong> (In a British accent) This is Phoebe Buffay. I was wondering, please, if-if it’s not too much trouble, please, umm, might I speak to Miss Emily Waltham, please?</p><blockquote><p>（用英国口音）这是菲比·布菲。我在想，如果不是太麻烦的话，我能和艾米丽·沃尔瑟姆小姐说话吗？</p></blockquote><p><strong>Housekeeper:</strong> Miss Waltham, is at the rehearsal dinner and it’s not polite to make fun of people. Goodbye.</p><blockquote><p>沃尔瑟姆小姐，在排练晚宴上，取笑别人是不礼貌的。再见。</p></blockquote><p><strong>Phoebe Buffay:</strong> No no no, I’ll be nice, I swear!!! Could you just give me the number for where they are?</p><blockquote><p>不，不，我会很好的，我发誓！！！你能告诉我他们在哪里吗？</p></blockquote><p><strong>Housekeeper:</strong> I’m afraid, I’m not at liberty to divulge that information.</p><blockquote><p>恐怕我无权泄露这些信息。</p></blockquote><p><strong>Phoebe Buffay:</strong> Ok, somebody is on their way to ruin wedding okay. And I have to warn somebody, alright. So if you don’t give me that number then I’m going to come over there and kick your snooty ass all the way to New Glocken..shire.</p><blockquote><p>好吧，有人要破坏婚礼了，好吧。我必须警告某人，好吗。所以如果你不给我那个号码，我就去那里踢你的臭屁股，一直踢到新格洛克郡。</p></blockquote><p><strong>Housekeeper:</strong> Hangs up.</p><blockquote><p>挂断。</p></blockquote><p><strong>Phoebe Buffay:</strong> Hello, Hello. Ohh, OHH, she knew I could kick her ass.</p><blockquote><p>你好，你好。哦，哦，她知道我可以踢她的屁股。</p></blockquote><hr><p>🎬 <em>Rehearsal dinner hall. Ross and Emily are standing in the reception area. Monica arrives with her parents.</em></p><blockquote><p>🎬 <em>排练宴会厅。罗斯和艾米丽站在接待区。莫妮卡和她的父母一起到达。</em></p></blockquote><p><strong>Monica Geller:</strong> Hey.</p><blockquote><p>嘿。</p></blockquote><p><strong>Ross Geller:</strong> (Ross hugs his mom and dad)Hi. Mom. Dad.</p><blockquote><p>（罗斯拥抱他的爸爸妈妈）嗨。妈妈。爸爸。</p></blockquote><p>Mrs. Geller: Sweetheart. Oh sorry were late, my fault, I insisted on riding the tube.</p><blockquote><p>亲爱的。哦，对不起，我们迟到了，是我的错，我坚持坐地铁。</p></blockquote><p>Mr. Geller: (embarrassed) Judy, the kids..</p><blockquote><p>（尴尬地）朱迪，孩子们。。</p></blockquote><p>Mrs. Geller: Jack, that’s what they call the subway.</p><blockquote><p>杰克，那就是他们所说的地铁。</p></blockquote><p>Mr. Geller: Ohh, I thought that you....</p><blockquote><p>哦，我还以为你。。。。</p></blockquote><p>Ross and **Monica Geller: **Dad, dad. We got it!! We Got It!!!</p><blockquote><p>罗斯和<strong>莫妮卡·盖勒：</strong>爸爸，爸爸。我们成功了！！我们明白了！！！</p></blockquote><p><strong>Emily:</strong> Ohh, here comes my dad and stepmum. Mister and Misses Geller, this is Steven and Andrea Waltham.</p><blockquote><p>哦，我爸爸和继母来了。盖勒先生和小姐，这是史蒂文和安德里亚·沃尔瑟姆。</p></blockquote><p>Mr. Waltham: (Shaking everyone&#39;s hand.) Hello. Hello. How do you do? How do you do? Very nice to meet you. (Looking over at his wife.) Darling it’s the Gellers. (She pays no attention she’s talking on a cellular phone.) (Louder) Darling, it’s the Gellers. (She’s still not responding.) She’s very self-absorbed, you know. I should never have married her.</p><blockquote><p>（和大家握手）你好。你好你好？你好？很高兴认识你。（看着他的妻子）亲爱的，是盖勒夫妇。（她没有注意到她在用手机说话。）（大声一点）亲爱的，是盖勒夫妇。（她仍然没有反应。）你知道，她非常专心致志。我不该娶她。</p></blockquote><p>Mrs. Waltham: (Looking evilly at her husband) Sorry, what?</p><blockquote><p>（邪恶地看着她的丈夫）对不起，什么？</p></blockquote><p>Mr. Waltham: It’s the Gellers!</p><blockquote><p>是盖勒家！</p></blockquote><p>Mrs. Waltham: Where?</p><blockquote><p>在哪里？</p></blockquote><p>Mr. Waltham: Well there’s one (pointing towards Jack) and there’s another (pointing towards Judy).</p><blockquote><p>有一个（指着杰克）还有一个（指着朱迪）。</p></blockquote><p>Mrs. Waltham: Lovely to meet you.</p><blockquote><p>很高兴见到你。</p></blockquote><p>Mr. Waltham: Terribly nice of you to offer to pay for half the wedding. (He hand a multipage bill to Jack.)</p><blockquote><p>非常感谢你提出支付婚礼的一半费用。（他递给杰克一张多页的钞票。）</p></blockquote><p>Mr. Geller: Ohh forget it. Too hell with tradition, we’re happy to do it.</p><blockquote><p>哦，算了吧。传统太糟糕了，我们很乐意这么做。</p></blockquote><p>Mrs. Geller: We know how expensive weddings can be, besides this may be the only wedding we get to throw (patting Monica on the shoulder.).</p><blockquote><p>我们知道婚礼有多贵，而且这可能是我们唯一可以举办的婚礼（拍莫妮卡的肩膀）。</p></blockquote><p><strong>Monica Geller:</strong> Ha ha, a joke that’s funny in all countries.</p><blockquote><p>哈哈，一个在所有国家都很有趣的笑话。</p></blockquote><p><em>(Ross quickly directs the families to their tables.)</em></p><blockquote><p><em>（罗斯很快将这些家庭带到他们的桌子上。）</em></p></blockquote><hr><p>🎬 <em>Chandler and Joey are standing by the kitchen entrance. A waiter comes out.</em></p><blockquote><p>🎬 <em>钱德勒和乔伊站在厨房门口，一个服务员走了出来。</em></p></blockquote><p><strong>Waiter:</strong> Sir? (Looking at Joey.)</p><blockquote><p>先生？（看着乔伊。）</p></blockquote><p><strong>Joey Tribbiani:</strong> What’s in it?</p><blockquote><p>里面有什么？</p></blockquote><p><strong>Waiter:</strong> Goat cheese, water chestnuts, and panchetta. (Joey Looks down disgustingly at the food.)</p><blockquote><p>山羊奶酪、荸荠和薄饼。（乔伊厌恶地低头看着食物。）</p></blockquote><p><strong>Joey Tribbiani:</strong> (Looking up at the waiter)That’s not food...No, I don’t, no...(Taps Chandler on the shoulder.) Everything&#39;s different here...I want to go home. I...I miss my family. I miss the coffee house. I can’t even remember what Phoebe looks like.</p><blockquote><p>（抬头看着服务员）那不是食物…不，我不，不…（轻拍钱德勒的肩膀）这里一切都不一样…我想回家。我…我想念我的家人。我想念咖啡馆。我都不记得菲比长什么样了。</p></blockquote><p><strong>Chandler Bing:</strong> Joey, it’s been three days, okay.. Your just a little homesick, Okay. Would you just try to relax. Just, just try to enjoy yourself.</p><blockquote><p>乔伊，已经三天了，好吧。。你只是有点想家，好吧。你能试着放松一下吗。只是，只是试着享受一下。</p></blockquote><p><strong>Joey Tribbiani:</strong> (Pointing at Chandler.) Your different here too. Your mean in England. (Chandler throws his hands up to his head in frustration. They walk away from each other.)</p><blockquote><p>（指着钱德勒）你在这里也不一样。你的意思是在英国。（钱德勒沮丧地把手举到头上。他们彼此走开了。）</p></blockquote><p>[Camera pans to the Geller family table. Ross, Rachel, Mr. and Mrs. Geller are there.]</p><blockquote><p>[镜头移到盖勒家的桌子上。罗斯、瑞秋、盖勒先生和夫人在那里。]</p></blockquote><p>Mr. Geller: (Looking at ht wedding bill.) What the hell!!!</p><blockquote><p>（看着ht婚礼账单。）见鬼！！！</p></blockquote><p><strong>Ross Geller:</strong> what’s up, Dad?</p><blockquote><p>怎么了，爸爸？</p></blockquote><p>Mr. Geller: This bill for my half of the wedding. it’s insane.</p><blockquote><p>这是我婚礼一半的账单。这太疯狂了。</p></blockquote><p>Mrs. Geller: How could it be so much? The receptions at their house.</p><blockquote><p>怎么会这么多？他们家的招待会。</p></blockquote><p>Mr. Geller: (Pointing items out on the bill.) Flowers, liquor, recarpet first floor. New guest bath, landscaping. I’m paying to remodel this guys house. (Angrily gets up.) I’m going to give that son on a bitch, a piece of my mind.</p><blockquote><p>（指着账单上的项目。）鲜花，酒，一楼的咖啡。新客人浴室，景观美化。我付钱来改造这所房子。（怒气冲冲地站起来）我要狠狠揍那个狗娘养的，狠狠揍他一顿。</p></blockquote><p><strong>Ross Geller:</strong> (Holding him back.)Dad, dad, please. Look I don’t want anything to upset Emily tonight. Alright, she&#39;s had a hard enough couple of days as it is. (Picks up the bill.) Now here, here, let me go talk to him, okay?</p><blockquote><p>（拦住他）爸爸，爸爸，求你了。听着，我今晚不想让艾米丽难过。好吧，她已经够辛苦的了。（拿起账单）现在，让我去和他谈谈，好吗？</p></blockquote><p>Mr. Geller: And you tell him no one takes advantage of the Gellers.</p><blockquote><p>你告诉他没有人利用盖勒家。</p></blockquote><p>Mrs. Geller: Ooh, Jack....(He looks over to her) Sometimes I forget how powerful you can be. (They embrace and kiss passionately.)</p><blockquote><p>噢，杰克……（他看着她）有时候我忘了你有多强大。（他们热情地拥抱和亲吻。）</p></blockquote><p><strong>Monica Geller:</strong> (Looking nauseous from her parents kissing.) And I’m going to go get drunk. (Gets up to get a drink.)</p><blockquote><p>（从她父母的接吻中看起来很恶心。）我要去喝醉了。（起身去喝一杯。）</p></blockquote><hr><p>🎬 <em>An airport in New York.</em></p><blockquote><p>🎬 <em>纽约的一个机场</em></p></blockquote><p><strong>Rachel Green:</strong> (Running to the ticket counter) Ooh, ooh, ooh,ooh,ooh. (Slightly out of breath) Hi.</p><blockquote><p>（跑到售票处）哦，哦，哦，哦，哦，哦。（有点上气不接下气）嗨。</p></blockquote><p><strong>Ticket Agent:</strong> (Cheerfully.) Hello.</p><blockquote><p>（高兴地）你好。</p></blockquote><p><strong>Rachel Green:</strong> (Faking cheerfulness.) Hello. Umm, when is your next flight to London?</p><blockquote><p>（假装高兴）你好。嗯，你下一班去伦敦的航班是什么时候？</p></blockquote><p><strong>Ticket Agent:</strong> (looking at her computer terminal) There’s one leaving in thirty minutes.</p><blockquote><p>（看着她的电脑终端）30分钟后还有一个。</p></blockquote><p><strong>Rachel Green:</strong> Ohh, good.</p><blockquote><p>哦，很好。</p></blockquote><p><strong>Ticket Agent:</strong> And I do have one seat left.</p><blockquote><p>我还有一个座位。</p></blockquote><p><strong>Rachel Green:</strong> Ohh, thank you, thank you, thank you.</p><blockquote><p>哦，谢谢，谢谢，谢谢。</p></blockquote><p><strong>Ticket Agent:</strong> The last minute fare on this ticket is twenty seven hundred dollars.</p><blockquote><p>这张票的最后一分钟票价是两千七百美元。</p></blockquote><p><strong>Rachel Green:</strong> (looking through her wallet.) Ohh, I just don’t think I have enough left on my credit card.</p><blockquote><p>（翻了翻钱包。）哦，我觉得我的信用卡上的钱不够了。</p></blockquote><p><strong>Ticket Agent:</strong> Well you can split it with another credit card.</p><blockquote><p>嗯，你可以用另一张信用卡把它分开。</p></blockquote><p><strong>Rachel Green:</strong> Ohh, okay, how about five. (She hands her all the credit cards.) Ohh, thank you.</p><blockquote><p>哦，好吧，五个怎么样。（她把所有的信用卡都递给了她。）哦，谢谢。</p></blockquote><p><strong>Ticket Agent:</strong> I’m just going to need to see your passport.</p><blockquote><p>我只是想看看你的护照。</p></blockquote><p><strong>Rachel Green:</strong> (Looking through her purse.) Okay, you know what? I don’t have it, but I can tell you exactly where it is on my night stand, and...okay. But you know what? I have my drivers license and I have a twenty. (She slides it across the counter.)</p><blockquote><p>（翻钱包）好吧，你知道吗？我没有，但我可以告诉你它在我的床头柜上的确切位置，好的。但是你知道吗？我有我的驾驶执照，我有一张20美元的支票。（她把它滑过柜台。）</p></blockquote><p><strong>Ticket Agent:</strong> (Slides the twenty back and tosses her credit card onto the counter.)</p><blockquote><p>（把20号滑回去，把她的信用卡扔到柜台上。）</p></blockquote><hr><p>🎬 <em>The Rehearsal dinner hall. Ross is at the Walthams’ table discussing the bill.</em></p><blockquote><p>🎬 <em>排练宴会厅。罗斯在沃尔瑟姆家的桌子旁讨论账单。</em></p></blockquote><p><strong>Ross Geller:</strong> Look, face it, my father is not going to pay for the build-in barbecue and believe me you can kiss you gazebo goodbye. Now I might be able to get you the new lawn.</p><blockquote><p>听着，面对现实吧，我父亲不会为内置烤肉付钱的，相信我，你可以和露台吻别。现在我也许能给你弄到新草坪了。</p></blockquote><p>Mr. Waltham: Ahh, then you have to give us the lawn ornaments.</p><blockquote><p>啊，那你得把草坪装饰物给我们。</p></blockquote><p><strong>Ross Geller:</strong> I go back there with lawn ornaments, he’s going to laugh in my face.</p><blockquote><p>我带着草坪装饰回去，他会当着我的面笑的。</p></blockquote><p>Mrs. Waltham: This is ridiculous. I mean we had an agreement. (Ross looks frustrated. She begins to scream at her husband.) Will you say something, Steven?! Please!!!</p><blockquote><p>这太荒谬了。我是说我们有协议。（罗斯看起来很沮丧。她开始对丈夫尖叫。）你能说点什么吗，史蒂文？！请</p></blockquote><p>Mr. Waltham: Don’t take that tone with me. (She looks evilly at him.) All-all right you can. (He looks over at Ross and Shrugs.)</p><blockquote><p>别用那种语气跟我说话。（她邪恶地看着他）好吧，你可以。（他看着罗斯耸耸肩。）</p></blockquote><hr><p>🎬 <em>The Girls apartment. Phoebe is dialing the phone and Rachel runs in the door.</em></p><blockquote><p>🎬 <em>女孩公寓。菲比正在拨电话，瑞秋跑进了门。</em></p></blockquote><p><strong>Rachel Green:</strong> (Running to her room.) Hi, Pheebs.</p><blockquote><p>（跑回她的房间）嗨，菲比。</p></blockquote><p><strong>Phoebe Buffay:</strong> (Looking relieved. She puts down the phone.) Oh thank god. Oh, you changed your mind. Oh, look I know you probably want to be alone, and you don’t want to talk about it, that’s fine. I just want you to know, I think you are doing the right thing and...</p><blockquote><p>（看起来松了一口气。她放下电话。）哦，感谢上帝。哦，你改变主意了。哦，听着，我知道你可能想一个人呆着，你不想谈论这件事，没关系。我只是想让你知道，我认为你做的是对的，而且。。。</p></blockquote><p><strong>Rachel Green:</strong> (Running back out the door with her passport.) Bye, Pheebs.</p><blockquote><p>（拿着护照跑回门外）再见，菲比。</p></blockquote><p><strong>Phoebe Buffay:</strong> (Trying to get up.) Wait!! Where are you going?! What are you doing?! No!! Wait!! (Not able to get up.) God!! Why am I always pregnant when she does that?!</p><blockquote><p>（试图站起来）等等！！你要去哪里？！你在做什么？不等待（站不起来）天哪！！为什么她这么做的时候我总是怀孕？！</p></blockquote><hr><p>🎬 <em>The Rehearsal Dinner Hall. Chandler, Joey, Ross, Emily, Monica, and all the bridal party are seated at the table. Chandler gets up to make a toast.</em></p><blockquote><p>🎬 <em>彩排宴会厅。钱德勒、乔伊、罗斯、艾米丽、莫妮卡和所有的婚礼派对都坐在桌旁。钱德勒站起来敬酒。</em></p></blockquote><p><strong>Chandler Bing:</strong> I’d like to toast, Ross and Emily. Of course, my big toast will be tomorrow at the wedding, so this is kind of my little toast or Melba toast, if you will. (No one in the room laughs. He starts to get flustered.) Okay. I known Ross for a long time. In fact, I knew him when he was going out with his first girlfriend. (Ross looks embarrassed.) And I thought things were going to work out for him..Until the day he over inflated her. (He laughs. Jack looks at Judy and no one in the room laughs.) Ohh, Dear God.. (A cellular phone rings.)</p><blockquote><p>我想干杯，罗斯和艾米丽。当然，我的大吐司将在明天的婚礼上，所以这是我的小吐司或梅尔巴吐司，如果你愿意的话。（房间里没人笑。他开始慌乱起来。）好的。我认识罗斯很久了。事实上，他和第一个女朋友约会时我就认识他了。（罗斯看起来很尴尬。）我还以为他会成功的……直到有一天他给她过度充气。（他笑了。杰克看着朱迪，屋里没有人笑。）哦，亲爱的上帝。。（手机响了。）</p></blockquote><p>Mrs. Waltham: Hello, Waltham Interiors.</p><blockquote><p>你好，沃尔瑟姆室内设计公司。</p></blockquote><p><strong>Phoebe Buffay:</strong> Oh, hi, Mrs. Waltham. I need to speak with ether one of the best men, or Ross’s sister Monica.</p><blockquote><p>哦，嗨，沃尔瑟姆太太。我需要找一个最好的男人或者罗斯的妹妹莫妮卡谈谈。</p></blockquote><p>Mrs. Waltham: Who is this?</p><blockquote><p>这是谁？</p></blockquote><p><strong>Phoebe Buffay:</strong> Oh, I’m Phoebe Buffay. I’m one of Ross’s best friends.</p><blockquote><p>哦，我是菲比·布菲。我是罗斯最好的朋友之一。</p></blockquote><p>Mrs. Waltham: Well, if you’re on e of Ross’s best friends, why aren’t you here?</p><blockquote><p>好吧，如果你在罗斯最好朋友的e台上，你为什么不在这里？</p></blockquote><p><strong>Phoebe Buffay:</strong> Yeah, um, I can’t fly. I’m having my brother’s babies.</p><blockquote><p>是的，嗯，我不会飞。我要生我哥哥的孩子了。</p></blockquote><p>Mrs. Waltham: Oh, am I on the radio?</p><blockquote><p>哦，我在广播里吗？</p></blockquote><p><strong>Phoebe Buffay:</strong> No..umm, could I talk to one of them? It’s very very important.</p><blockquote><p>不……嗯，我能和他们中的一个谈谈吗？这非常重要。</p></blockquote><p>Mrs. Waltham: No, I’m bored with you now. I’m going to cut you off. (She hangs up.)</p><blockquote><p>不，我现在对你感到厌烦了。我要打断你的话。（她挂断了。）</p></blockquote><p><strong>Phoebe Buffay:</strong> Ohh! Okay, I’m going to have to kick her ass too.</p><blockquote><p>哦！好吧，我也得踢她的屁股。</p></blockquote><p><strong>Chandler Bing:</strong> (Continuing his toast.) And I’m sure we’re all very excited that Ross and Emily are getting married at Montgomery Hall. I mean to think, my friend getting married in Monty Hall. (No reaction from the people.) Ohh, come on!! Monty Hall!! Lets make a Deal!! Come on, you people!! All right, forget it!! Congratulations, Ross and Emily. (He sits down.)</p><blockquote><p>（继续祝酒）我相信罗斯和艾米丽要在蒙哥马利大厅结婚了，我们都很兴奋。我想，我的朋友在蒙蒂霍尔结婚了。（人们没有反应。）哦，来吧！！蒙蒂霍尔！！让我们做个交易！！来吧，你们这些人！！好吧，算了吧！！恭喜你，罗斯和艾米丽。（他坐了下来。）</p></blockquote><p><strong>Joey Tribbiani:</strong> Hey, best man number two, Joey Tribbiani. Now I’m not good with the jokes like Chandler here. Boy...but ahh, I just want to say congratulation to the happy couple. I first met Ross in this coffee house back home...Home...New York City...Where everybody knows my name. Well anyway, I love you guys. (pointing at everyone.) But not as much as I love America. (Looking at Chandler.) Could we please..go home now?</p><blockquote><p>嘿，二号伴郎乔伊·特里比亚尼。现在我不擅长像钱德勒这样的笑话。男孩…但是啊，我只想向这对幸福的夫妇表示祝贺。我第一次见到罗斯是在家里的咖啡馆里…家里…纽约市…那里每个人都知道我的名字。不管怎样，我爱你们。（指着每个人）但没有我那么爱美国。（看着钱德勒）我们现在可以回家了吗？</p></blockquote><p><em>(One of the bridesmaids, Felicity, puts her arm around Joey.)</em></p><blockquote><p><em>（其中一位伴娘费利西蒂挽着乔伊。）</em></p></blockquote><p><strong>Felicity:</strong> (Putting her arm around Joey.) Are you going home? I was hoping to get to know you better.</p><blockquote><p>（搂着乔伊）你要回家吗？我希望能更好地了解你。</p></blockquote><p><strong>Joey Tribbiani:</strong> (Putting his arm around her.) I’m not going anywhere, sweetheart.</p><blockquote><p>（搂住她）我哪儿也不去，甜心。</p></blockquote><hr><p>🎬 <em>Later that evening at the rehearsal dinner. Chandler and Monica are sitting on a sofa. Chandler is covering his face in embarrassment because of the toast.</em></p><blockquote><p>🎬 <em>那天晚上晚些时候彩排晚宴上。钱德勒和莫妮卡坐在沙发上。钱德勒因为祝酒而尴尬地捂着脸。</em></p></blockquote><p><strong>Monica Geller:</strong> I was laughing. (Patting him on the knee.)</p><blockquote><p>我在笑。（拍拍他的膝盖。）</p></blockquote><p><strong>Chandler Bing:</strong> Out loud?</p><blockquote><p>大声说？</p></blockquote><p><strong>Monica Geller:</strong> Well I didn’t want everyone to think I was stupid.</p><blockquote><p>我不想让每个人都认为我很愚蠢。</p></blockquote><p><strong>Chandler Bing:</strong> So how are you doing?</p><blockquote><p>那你怎么样？</p></blockquote><p><strong>Monica Geller:</strong> My mother’s driving me crazy, but Ross is getting married. I’m happy. (A drunken man approaches.) I’m not going to let anything spoil that.</p><blockquote><p>我妈妈快把我逼疯了，但罗斯要结婚了。我很高兴。（一个醉汉走近）我不会让任何事情破坏它。</p></blockquote><p><strong>Drunk Man:</strong> I just want to say that Ross is a wonderful young man.</p><blockquote><p>我只想说罗斯是个很棒的年轻人。</p></blockquote><p><strong>Monica Geller:</strong> Well, thanks, we like him.</p><blockquote><p>谢谢，我们喜欢他。</p></blockquote><p><strong>Drunk Man:</strong> My god!! You must have been a teenage when you had him. (Monica stares straight forward after the comment. Chandler tries to console her by patting her on the shoulder.)</p><blockquote><p>天哪！！你生他的时候一定是个十几岁的孩子。（莫妮卡在评论后直视着她。钱德勒拍拍她的肩膀试图安慰她。）</p></blockquote><p><em>(Ross and Emily’s parents are seated at a table. Ross is between them and they are discussing the wedding bill.)</em></p><blockquote><p><em>（罗斯和艾米丽的父母坐在一张桌子旁。罗斯在他们中间，他们正在讨论婚礼账单。）</em></p></blockquote><p>Mr. Geller: There’s no way in hell, I’m paying for it.</p><blockquote><p>地狱里没有办法，我要付钱。</p></blockquote><p><strong>Ross Geller:</strong> Look, were down to just one point. Could we please, maybe just settle it after the wedding.</p><blockquote><p>看，我们只谈了一点。我们可以在婚礼结束后再谈吗。</p></blockquote><p>Mr. Geller: All-right fine, but I just want to say, I’m not paying for your wine cellar. You thieving, would be speaking German if it weren’t for us, cheap little man. (Emily’s stepmum looks shocked. Jack and Judy get up and leave.)</p><blockquote><p>好吧，但我只想说，我不会为你的酒窖付钱。你这个小偷，要不是我们，你会说德语的，卑鄙小人。（艾米丽的继母看起来很震惊。杰克和朱迪站起来离开了。）</p></blockquote><p><em>(Chandler’s trying to console Monica.)</em></p><blockquote><p><em>（钱德勒试图安慰莫妮卡。）</em></p></blockquote><p><strong>Chandler Bing:</strong> The guy was hammered, okay? There’s no way, you look like Ross’s mother.</p><blockquote><p>那家伙被打了，好吗？不可能，你看起来像罗斯的妈妈。</p></blockquote><p><strong>Monica Geller:</strong> Then why would he say it?</p><blockquote><p>那他为什么这么说？</p></blockquote><p><strong>Chandler Bing:</strong> Because he’s crazy. Okay? He came up to me earlier and thanked me for my very moving performance in Titanic.</p><blockquote><p>因为他疯了。可以他早些时候来找我，感谢我在《泰坦尼克号》中非常感人的表演。</p></blockquote><p><strong>Monica Geller:</strong> Oh, my mother’s right. I’m never going to get married.</p><blockquote><p>哦，我妈妈说得对。我永远不会结婚。</p></blockquote><p><strong>Chandler Bing:</strong> Ahh, you know what? That is....Who wouldn’t want you?</p><blockquote><p>啊，你知道吗？那就是…谁不想要你？</p></blockquote><p><strong>Monica Geller:</strong> Ohh, Please?! I’m a single mom, with a thirty year old son!!</p><blockquote><p>哦，求你了？！我是单身妈妈，有一个三十岁的儿子！！</p></blockquote><hr><p>🎬 <em>The airport. Rachel runs up to the ticket counter.</em></p><blockquote><p>🎬 <em>机场。瑞秋跑到售票处。</em></p></blockquote><p><strong>Rachel Green:</strong> Hi, I’m back. Listen, I need to...</p><blockquote><p>嗨，我回来了。听着，我需要。。。</p></blockquote><p><strong>Ticket Agent:</strong> Hello.</p><blockquote><p>你好。</p></blockquote><p><strong>Rachel Green:</strong> Hello. I need to get on the 11 o&#39;clock flight.</p><blockquote><p>你好。我需要上11点的航班。</p></blockquote><p><strong>Ticket Agent:</strong> Oh I’m afraid that plane has already pulled away from the gate.</p><blockquote><p>噢，恐怕那架飞机已经离开登机口了。</p></blockquote><p><strong>Rachel Green:</strong> Okay, you know what/ You’re going to have to call that plane and tell them to swing around and come and pick me up.</p><blockquote><p>好吧，你知道你得给那架飞机打个电话，让他们转转过来接我。</p></blockquote><p><strong>Ticket Agent:</strong> I can’t do that.</p><blockquote><p>我不能那样做。</p></blockquote><p><strong>Rachel Green:</strong> Sure, you know what? Come on, we’ll just tell them that there was like a problem with like the &quot;engine&quot;.</p><blockquote><p>当然，你知道吗？来吧，我们会告诉他们“引擎”有问题。</p></blockquote><p><strong>Ticket Agent:</strong> I’m afraid I’m going to have to ask you to step aside, Miss.</p><blockquote><p>小姐，恐怕我得请你让开。</p></blockquote><p><strong>Rachel Green:</strong> Look, If I don’t get to London!! He is going to marry that other girl!!!</p><blockquote><p>听着，如果我到不了伦敦！！他要娶另一个女孩！！！</p></blockquote><p><strong>Ticket Agent:</strong> I can’t imagine why.</p><blockquote><p>我无法想象为什么。</p></blockquote><p><strong>Rachel Green:</strong> All right, you know what? I am not leaving here, until you call that plane back!! (She pounds her hand on the counter twice. The ticket agent counters by placing the closed sign on the counter and tapping it twice.)</p><blockquote><p>好吧，你知道吗？我不会离开这里，除非你把飞机叫回来！！（她用手在柜台上捶了两下。售票员把“关闭”的标志放在柜台上，然后轻敲两下，进行柜台操作。）</p></blockquote><hr><p>🎬 <em>Chandlers hotel room. Ross bursts into the room.</em></p><blockquote><p>🎬 <em>钱德勒酒店房间。罗斯冲进房间。</em></p></blockquote><p><strong>Ross Geller:</strong> (Screaming) I’m getting married today!! Whoo-hoo!!</p><blockquote><p>（尖叫）我今天要结婚了！！呜呼！！</p></blockquote><p><strong>Chandler Bing:</strong> (With the covers pulled up to his chin.) Morning, Ross.</p><blockquote><p>（把被子拉到下巴）早上好，罗斯。</p></blockquote><p><strong>Ross Geller:</strong> I’m getting married, to..day!!</p><blockquote><p>我要结婚了，到……天！！</p></blockquote><p><strong>Chandler Bing:</strong> Yeah you are!!</p><blockquote><p>是的，你是！！</p></blockquote><p><strong>Ross Geller:</strong> Ahh, whoo-hoo!!(He runs back out the door.</p><blockquote><p>啊，呜呼！！（他跑回门外。</p></blockquote><p><strong>Monica Geller:</strong> (Comes up for below the covers and looks concerned.) Do you think he knew I was here? (Chandler quickly looks at Monica not knowing what to say.)</p><blockquote><p>（走到封面下，看起来很担心。）你认为他知道我在这里吗？（钱德勒快速地看着莫妮卡，不知道该说什么。）</p></blockquote><p>Commercial Break</p><blockquote><p>商业休息</p></blockquote><hr><p>🎬 <em>Chandlers hotel room. Chandler and Monica are lying in the bed together talking. There’s an awkward air between them. They are both clutching the covers in from of them.</em></p><p><strong>Chandler Bing:</strong> Well I’ve-I’ve never done that with you before.</p><blockquote><p>嗯，我以前从未和你这样做过。</p></blockquote><p><strong>Monica Geller:</strong> (In am uneasy voice.) Nope. (She chuckles uneasily.)</p><blockquote><p>（用我不安的声音）不。（她不安地笑了。）</p></blockquote><p><strong>Chandler Bing:</strong> So, ahh, how are ya? How ya...How ya... You okay?</p><blockquote><p>那么，啊，你好吗？你好…你好…你还好吗？</p></blockquote><p><strong>Monica Geller:</strong> Yep, yep...You?</p><blockquote><p>是的，是的……你呢？</p></blockquote><p><strong>Chandler Bing:</strong> Yes...Yes..Uh-huh, You?(Looking over at her. She looks back.) We did you.</p><blockquote><p>是的……是的……嗯，你？（看着她。她回头。）我们杀了你。</p></blockquote><p><strong>Monica Geller:</strong> Well...I’d better get going.</p><blockquote><p>嗯……我得走了。</p></blockquote><p><strong>Chandler Bing:</strong> Oh yea yea, absolutely.</p><blockquote><p>哦，是的，绝对是。</p></blockquote><p><strong>Monica Geller:</strong> (Scoots towards the side of the bed.) Could you not look?</p><blockquote><p>（朝床边挪了挪）你能不能看一下？</p></blockquote><p><strong>Chandler Bing:</strong> I don’t want to look.</p><blockquote><p>我不想看。</p></blockquote><hr><p>🎬 <em>The Virgin Atlantic flight to London that Rachel is on.</em></p><blockquote><p>🎬 <em>瑞秋乘坐的维珍航空公司飞往伦敦的航班</em></p></blockquote><p><strong>Rachel Green:</strong> Ohhh.(she rhythmically taps her hands on the magazine on her lap.)</p><blockquote><p>哦。（她有节奏地用手轻拍膝盖上的杂志。）</p></blockquote><p><strong>Passenger:</strong> Ahh, ahh, excuse me.</p><blockquote><p>啊，啊，对不起。</p></blockquote><p><strong>Rachel Green:</strong> Yeah?</p><blockquote><p>是吗？</p></blockquote><p><strong>Passenger:</strong> If you’re planning on doing that throughout the entire flight. Please tell me now. So that I could that a sedative...or perhaps slip you one.</p><blockquote><p>如果你打算在整个飞行过程中都这样做。请现在告诉我。这样我就可以给你一片镇静剂……或者给你一片。</p></blockquote><p><strong>Rachel Green:</strong> Oh. I’m sorry. I’m very sorry. Sorry. (She hums and sighs happily.) It’s just, I’m ahh, I’m kinda excited. I’m, ahh, going to London to ahh, tell this guy that I love him and... (He puts his headphones on to ignore her.)</p><blockquote><p>哦。对不起。我很抱歉。对不起。（她高兴地哼哼着，叹息着。）只是，我啊，我有点兴奋。我啊，要去伦敦啊，告诉这个家伙我爱他，还有…（他戴上耳机不理她。）</p></blockquote><hr><p>🎬 <em>Joey enters his hotel room. The phone is ringing.</em></p><blockquote><p>🎬 <em>乔伊进入酒店房间，电话铃响了。</em></p></blockquote><p><strong>Joey Tribbiani:</strong> Hello?</p><blockquote><p>喂？</p></blockquote><p><strong>Phoebe Buffay:</strong> (Angrily.) Hey, were the hell have you been?!</p><blockquote><p>（愤怒地）嘿，你到底去了哪里？！</p></blockquote><p><strong>Joey Tribbiani:</strong> Hey. I spent the night out. I met this cute bridesmaid. She is so...</p><blockquote><p>嘿。我在外面过夜。我遇到了一个可爱的伴娘。她太。。。</p></blockquote><p><strong>Phoebe Buffay:</strong> I don’t want to hear about her!!</p><blockquote><p>我不想听她的事！！</p></blockquote><p><strong>Joey Tribbiani:</strong> Ahh Pheebs, you know you’re still my number one girl.</p><blockquote><p>啊，菲比，你知道你还是我的头号女孩。</p></blockquote><p><strong>Phoebe Buffay:</strong> No! No, we have an emergency. Okay? Rachel’s coming to London.</p><blockquote><p>不！不，我们有急事。好吗？瑞秋要来伦敦。</p></blockquote><p><strong>Joey Tribbiani:</strong> Ohh great!!!</p><blockquote><p>哦，太棒了！！！</p></blockquote><p><strong>Phoebe Buffay:</strong> No it’s not great. No, she’s coming to tell Ross that she loves him.</p><blockquote><p>不，不太好。不，她是来告诉罗斯她爱他。</p></blockquote><p><strong>Joey Tribbiani:</strong> (Confused.) But, he loves Emily?</p><blockquote><p>（困惑）但是，他爱艾米丽？</p></blockquote><p><strong>Phoebe Buffay:</strong> I KNOW THAT!!! You have to stop her!! She’s going to ruin the wedding!!</p><blockquote><p>我知道！！！你必须阻止她！！她会毁掉婚礼的！！</p></blockquote><p><strong>Joey Tribbiani:</strong> Okay.</p><blockquote><p>好的。</p></blockquote><p><strong>Phoebe Buffay:</strong> All right, so, okay...</p><blockquote><p>好吧，那么，好吧。。。</p></blockquote><p><strong>Joey Tribbiani:</strong> Hold on. Hold on. (Picking up a note pad and writing and reading the message aloud.) Rachel coming. Do...Something.</p><blockquote><p>等一下。等一下。（拿起便笺簿，大声读写信息。）瑞秋来了。做点什么。</p></blockquote><p><strong>Phoebe Buffay:</strong> Okay, so I’m done my part, okay. It’s your responsibility now, okay. The burden is off me, right?</p><blockquote><p>好了，我已经尽了我的责任，好了。现在是你的责任了，好了。责任在我身上，对吗？</p></blockquote><p><strong>Joey Tribbiani:</strong> Right!</p><blockquote><p>对！</p></blockquote><p><strong>Phoebe Buffay:</strong> So tell me about this girl?</p><blockquote><p>那跟我说说这个女孩吧？</p></blockquote><p><em>(The guys hotel room. Joey’s there. Chandler comes out of the bathroom in a robe.)</em></p><blockquote><p><em>（男人旅馆房间。乔伊在那里。钱德勒穿着长袍从浴室出来。）</em></p></blockquote><p><strong>Joey Tribbiani:</strong> Hey.</p><blockquote><p>嘿。</p></blockquote><p><strong>Chandler Bing:</strong> Hey.</p><blockquote><p>嘿。</p></blockquote><p><strong>Joey Tribbiani:</strong> Have you seen Monica?</p><blockquote><p>你看见莫妮卡了吗？</p></blockquote><p><strong>Chandler Bing:</strong> (Very defensive.) I’m not seeing Monica.</p><blockquote><p>（非常防御性。）我没有见到莫妮卡。</p></blockquote><p><strong>Joey Tribbiani:</strong> (With a confused look on his face.) What?</p><blockquote><p>（脸上带着困惑的表情）什么？</p></blockquote><p><strong>Chandler Bing:</strong> What?</p><blockquote><p>什么？</p></blockquote><p><strong>Joey Tribbiani:</strong> Look we’ve got to find her. Phoebe just called!! Rachel’s coming to tell Ross she loves him!!</p><blockquote><p>听着，我们得找到她。菲比刚打电话来！！瑞秋要来告诉罗斯她爱他！！</p></blockquote><p><strong>Chandler Bing:</strong> Oh my god!</p><blockquote><p>哦，我的天啊！</p></blockquote><p><strong>Joey Tribbiani:</strong> I know! That’s why we got to find Monica!! You know where she is?</p><blockquote><p>我知道！这就是为什么我们要找到莫妮卡！！你知道她在哪里吗？</p></blockquote><p><strong>Chandler Bing:</strong> No!! Okay!! What’s with the third degree?! Why don’t you just shine a light in my eyes?! (Joey looks totally confused.)</p><blockquote><p>不！！好吧！！第三度是怎么回事？！你为什么不照我的眼睛？！（乔伊看起来很困惑。）</p></blockquote><hr><p>🎬 <em>The plane. Rachel&#39;s telling her story to the passenger on her left. The one on her left is still wearing his headphones.</em></p><blockquote><p>🎬 <em>飞机。瑞秋正在向她左边的乘客讲述她的故事。她左边的那个人仍然戴着耳机。</em></p></blockquote><p><strong>Rachel Green:</strong> ...And so then I realized. All this stuff I had been doing. proposing to Joshua, lying to Ross about why I couldn’t come to the wedding. Was all just a way of...</p><blockquote><p>……然后我意识到。我一直在做的这些事。向约书亚求婚，向罗斯撒谎说我为什么不能来参加婚礼。这只是一种。。。</p></blockquote><p><strong>Passenger:</strong> (Frustrated he takes his headphones off.) Oh, oh oh!! I’m sorry, can I interrupt? You know I just want to say..That you are a horrible, horrible person.</p><blockquote><p>（沮丧的他摘下耳机。）哦，哦！！对不起，我能打断一下吗？你知道我只是想说……你是一个可怕的人。</p></blockquote><p><strong>Rachel Green:</strong> Ehh, pardon me?</p><blockquote><p>呃，对不起？</p></blockquote><p><strong>Passenger:</strong> You say you love this man, yet you’re about to ruin the happiest day of his life. I’m afraid I have to agree with you friend Pheebs.. This is a..this is a...terrible, terrible plan.</p><blockquote><p>你说你爱这个人，但你却要毁掉他一生中最快乐的一天。恐怕我不得不同意你朋友菲比的看法。这是一个……这是一个……可怕的计划。</p></blockquote><p><strong>Rachel Green:</strong> But he has to know how I feel!</p><blockquote><p>但他必须知道我的感受！</p></blockquote><p><strong>Passenger:</strong> But why? He loves this...this Emily person. No good can come of this.</p><blockquote><p>但为什么？他喜欢这个……这个爱米丽的人。这不会有什么好处的。</p></blockquote><p><strong>Rachel Green:</strong> (Sighing) Well I-I think your wrong.</p><blockquote><p>（叹气）我觉得你错了。</p></blockquote><p><strong>Passenger:</strong> Oh-no.(He bites his fist at her.)And by the way, it seems to be perfectly clear that you were on a break. (Rachel gasps and doesn’t know what to say. He puts his headphones back on.)</p><blockquote><p>哦，不。（他用拳头咬了她。）顺便说一句，很明显你是在休息。（瑞秋喘息着，不知道说什么。他把耳机重新戴上。）</p></blockquote><hr><p>🎬 <em>The church where Ross and Emily are to be married. Judy, Andrea, and Monica enter together.</em></p><blockquote><p>🎬 <em>罗斯和艾米丽结婚的教堂。朱迪、安德里亚和莫妮卡一起进入。</em></p></blockquote><p>Mrs. Geller: (Looking around at the chapel.) Oh my God! It’s like a fairyland.</p><blockquote><p>（环顾教堂）哦，我的天啊！它就像一个仙境。</p></blockquote><p>Mrs. Waltham: I know, it’s horrible isn’t it?</p><blockquote><p>我知道，这很可怕，不是吗？</p></blockquote><p><strong>Monica Geller:</strong> Well, I love it. I only hope my wedding looks this good.</p><blockquote><p>嗯，我喜欢。我只希望我的婚礼看起来这么好。</p></blockquote><p>Mrs. Geller: I just hope...</p><blockquote><p>我只是希望。。。</p></blockquote><p><strong>Monica Geller:</strong> (Angrily.) You can let some of them go by!(Judy and Andrea go to the front of the chapel. Joey approaches Monica.)</p><blockquote><p>（愤怒地）你可以让他们中的一些人过去！（朱迪和安德里亚走到教堂前面。乔伊走近莫妮卡。）</p></blockquote><p><strong>Joey Tribbiani:</strong> (Whispering.) Pisst, Monica. Alright, we really need to start looking out for Rachel. I’ll cover the front door. You watch that big hole at the back of the building and I got Chandler covering Ross.</p><blockquote><p>（小声说）小便，莫妮卡。好吧，我们真的需要开始寻找瑞秋。我来掩护前门。你看着大楼后面的那个大洞，我让钱德勒掩护罗斯。</p></blockquote><p><strong>Monica Geller:</strong> (Awkwardly.) Why would I care where Chandler is? You know uhh...You know sometimes I don’t even like Chandler.</p><blockquote><p>（尴尬地）为什么我会在乎钱德勒在哪里？你知道，嗯……你知道有时候我甚至不喜欢钱德勒。</p></blockquote><p><strong>Joey Tribbiani:</strong> Okay. (They both walk off to watch for Rachel.)</p><blockquote><p>好。（他们两个都走开去看瑞秋。）</p></blockquote><p><em>(Ross and chandler are standing next to the alter. Ross is practicing for the wedding.)</em></p><blockquote><p><em>（罗斯和钱德勒站在圣坛旁边。罗斯正在为婚礼练习。）</em></p></blockquote><p><strong>Ross Geller:</strong> (Using a slightly different inflection for each.) I do. I do. I do.</p><blockquote><p>（对每个词使用稍微不同的屈折变化。）我喜欢。我喜欢。我喜欢。</p></blockquote><p><strong>Chandler Bing:</strong> Oh yea, your right. It’s the second one.</p><blockquote><p>哦，是的，你说得对。这是第二个。</p></blockquote><p><strong>Ross Geller:</strong> (Very Nervous)Really?</p><blockquote><p>（非常紧张）真的吗？</p></blockquote><p>[Scene: Joey’s in the front entrance watching for Rachel. The bridesmaid he met at the rehearsal dinner come in.)<br><strong>Felicity:</strong> (In a sexy voice.)Hello Joey.</p><blockquote><p>（用性感的声音）你好，乔伊。</p></blockquote><p><strong>Joey Tribbiani:</strong> Hey, Felicity.</p><blockquote><p>嘿，费利西蒂。</p></blockquote><p><strong>Felicity:</strong> Umm, I thought about you all day.</p><blockquote><p>嗯，我整天都在想你。</p></blockquote><p><strong>Joey Tribbiani:</strong> Yeah.</p><blockquote><p>是的。</p></blockquote><p><strong>Felicity:</strong> Um-hum. Talk New York to me again.</p><blockquote><p>嗯哼。再跟我谈谈纽约。</p></blockquote><p><strong>Joey Tribbiani:</strong> (In a New York accent.) Fuggetaboutit. (She giggles.) How you doin?</p><blockquote><p>（带着纽约口音）福格塔布特。（她咯咯笑）你好吗？</p></blockquote><p><strong>Felicity:</strong> Mmm. (She pushes him up against the wall and they begin to kiss.)</p><blockquote><p>嗯。（她把他推到墙上，他们开始接吻。）</p></blockquote><p><strong>Joey Tribbiani:</strong> Oh, yeah.</p><blockquote><p>哦，是的。</p></blockquote><p><em>(Back in the chapel. The parents are still fighting over the bill. Ross is refereeing.)</em></p><blockquote><p><em>（回到礼拜堂。父母还在为账单争吵。罗斯是裁判。）</em></p></blockquote><p>Mrs. Geller: There’s nothing to discuss. We’re not paying for your wine cellar.</p><blockquote><p>没什么好讨论的。我们不会为你的酒窖付钱。</p></blockquote><p>Mr. Waltham: (Pleading.) You-you have to meet me in the middle here.</p><blockquote><p>Waltham先生：（恳求）你必须在这里与我会面。</p></blockquote><p>Mr. Geller: (Forcefully.) Hey, you keep pushing me on this, my foots going to meet the middle of your ass.</p><blockquote><p>（用力地）嘿，你一直在推我，我的脚会碰到你的屁股中间。</p></blockquote><p><strong>Ross Geller:</strong> Dad!! (Emily comes running in.)</p><blockquote><p>爸爸！！（艾米丽跑了进来。）</p></blockquote><p><strong>Emily:</strong> What-what’s going on?!</p><blockquote><p>怎么回事？！</p></blockquote><p><strong>Ross Geller:</strong> Nothing, nothing. Everything&#39;s under control.</p><blockquote><p>没什么，没什么。一切都在控制之中。</p></blockquote><p>Mr. Waltham: You want a piece of me, sir? Is that what your saying? (Pointing at Jack and poking him) You want a piece of me?</p><blockquote><p>先生，你想要我的一部分吗？你是这么说的吗？（指着杰克，戳了戳他）你想从我身上分一块吗？</p></blockquote><p><strong>Ross Geller:</strong> (Stepping in between them.)Okay! Okay! That’s it!! Parents!! Parents!! Back away!! All right, this is our wedding day! From now on everyone gets along, and if I hear one more word. NO GRANDCHILDREN! (Pointing at his mother.) That’s right!!</p><blockquote><p>（站在他们中间）好的！可以就这样！！父母父母退后！！好了，今天是我们的婚礼！从现在起，每个人都相处融洽，如果我再听到一个字。没有孙子！（指着他的母亲）没错！！</p></blockquote><p>Mr. Geller: Okay, okay.</p><blockquote><p>好的，好的。</p></blockquote><p>Mr. Waltham: Sorry old boy, sorry. Sorry. Sorry. (Them all walk away. As he leaves he mutters to Jack.) I could kill you with my thumb, you know.</p><blockquote><p>对不起，老家伙，对不起。很抱歉很抱歉（他们都走开了。他离开时对杰克喃喃自语。）你知道，我可以用我的拇指杀了你。</p></blockquote><p><strong>Emily:</strong> What was all that about?</p><blockquote><p>那是怎么回事？</p></blockquote><p><strong>Ross Geller:</strong> (Sighing.) It was...This disagreement over...(She sighs. Ross notices her in her wedding dress.) My god. You...you look beautiful.</p><blockquote><p>（叹气）这是……关于……的分歧。（她叹气。罗斯注意到她穿着婚纱。）我的上帝。你…你看起来很漂亮。</p></blockquote><p><strong>Emily:</strong> (Giggles.) Ohh...(She realizes that she’s in her gown.) Oh! You were not meant to see me before the wedding. It’s bad luck.</p><blockquote><p>（咯咯笑）哦…（她意识到她穿着她的礼服。）哦！你不该在婚礼前见我。真倒霉。</p></blockquote><p><strong>Ross Geller:</strong> You know what, I think we’ve had all the bad luck we’re going to have. (He hugs her.)</p><blockquote><p>你知道吗，我想我们已经经历了所有的厄运。（他拥抱着她。）</p></blockquote><p><em>(The front entrance. Joey and the bridesmaid are up against the wall kissing. Rachel comes in the door and walks by Joey unnoticed. She walks into the chapel and sees Ross and Emily kissing. She looks as though she wants to cry. Emily walks away and Ross turns and sees Rachel standing there.)</em></p><blockquote><p><em>（前门。乔伊和伴娘靠墙接吻。瑞秋走进门，无意中从乔伊身边走过。她走进教堂，看到罗斯和艾米莉接吻。她看起来好像想哭。艾米莉走开了，罗斯转过身，看到瑞秋站在那里。）</em></p></blockquote><p><strong>Ross Geller:</strong> My God. Rachel! (He walks towards her, grasps her hands and kisses her on the cheek.) Your here. I can’t believe it. (She giggles.) What happen? Why are you here?</p><blockquote><p>我的天啊。瑞秋！（他走向她，握住她的手，亲吻她的脸颊。）你的手在这里。真不敢相信。（她咯咯地笑）发生了什么事？你为什么在这里？</p></blockquote><p><strong>Rachel Green:</strong> Well I just came...(She touches him near his heart. She’s almost in tears.) I just needed to tell you...(Looking into his eyes. She takes a deep breath.) Congratulations. (He hugs her. She can barely hold back the tears.)</p><blockquote><p>我刚来…（她抚摸着他的心。她几乎要哭了。）我只想告诉你…（看着他的眼睛。她深吸了一口气。）祝贺你。（他拥抱着她，她几乎忍不住流泪。）</p></blockquote><hr><p>🎬 <em>Camera fades to one of the band members playing guitar at the wedding. The chapel is full of guest. A groomsmen escorts a bridesmaid down the isle. Joey is waiting with Mrs. Waltham to escort he down the isle. A cellular phone rings.</em></p><blockquote><p>🎬 <em>在婚礼上，一名乐队成员弹吉他，镜头淡出。小教堂里挤满了客人。一名伴郎护送一名伴娘下岛。乔伊正和沃尔瑟姆夫人一起等着护送他下岛。手机响了。</em></p></blockquote><p>Mrs. Waltham: (Answering the phone.) Hello, Waltham Interiors.</p><blockquote><p>（接电话）你好，沃尔瑟姆室内设计公司。</p></blockquote><p><strong>Phoebe Buffay:</strong> Mrs. Waltham. Hi. It’s Phoebe again.</p><blockquote><p>沃尔瑟姆太太。你好又是菲比。</p></blockquote><p>Mrs. Waltham: (Throws her head back in disgust.) Why?!</p><blockquote><p>（厌恶地把头往后仰）为什么？！</p></blockquote><p><strong>Phoebe Buffay:</strong> Yea. Can I please, please, please talk to one of the best men? This is going to be the last time I promise.</p><blockquote><p>是的。我能不能请最好的男人谈谈？这将是我最后一次保证。</p></blockquote><p>Mrs. Waltham: (Slapping the phone into Joey’s chest.) Joey there’s a girl on the phone for you.</p><blockquote><p>（把电话打到乔伊的胸前）乔伊，有个女孩在给你打电话。</p></blockquote><p><strong>Joey Tribbiani:</strong> (Smiling.) Ohh great!! (Putting the phone to his ear.) Hello. (He begins to escort her down the aisle.)</p><blockquote><p>（微笑）哦，太好了！！（把电话放在他耳边）你好。（他开始陪她走下走道。）</p></blockquote><p><strong>Phoebe Buffay:</strong> Did you stop Rachel?</p><blockquote><p>你阻止瑞秋了吗？</p></blockquote><p><strong>Joey Tribbiani:</strong> No, but it’s okay. She just came in and gave him a hug, that it.</p><blockquote><p>没有，但没关系。她只是进来给了他一个拥抱，就这样。</p></blockquote><p><strong>Phoebe Buffay:</strong> So nothing got ruined?</p><blockquote><p>所以什么都没有被破坏？</p></blockquote><p><strong>Joey Tribbiani:</strong> No.</p><blockquote><p>没有。</p></blockquote><p><strong>Phoebe Buffay:</strong> Oh that’s so great! Ohh, so what’s going on now?</p><blockquote><p>哦，太棒了！哦，那现在怎么了？</p></blockquote><p><strong>Joey Tribbiani:</strong> Ah, I’m-I’m walking down the aisle...Still walking. (Mrs. Waltham takes her place.) I’m about to pass the bridesmaid I hooked up with last night. (Looking at the bridesmaid.) Hey! (Talking to Phoebe.) I told her &quot;Hey.&quot; And now I’m at the front with Ross. It’s Phoebe. (He shows Ross the phone.) He looks pretty mad. Uh...I’d better go.</p><blockquote><p>啊，我，我正在走道上……还在走。（沃尔瑟姆夫人接替了她的位置）我正要从昨晚和我搭讪的伴娘身边经过。（看着伴娘）嘿！（和菲比说话）我告诉她“嘿”，现在我和罗斯站在前面。是菲比。（他把电话给罗斯看）他看起来很生气。嗯……我最好走了。</p></blockquote><p><strong>Phoebe Buffay:</strong> No!! wait, wait, wait!! Oh please, hold it up so I can listen. (Joey looks at Ross and holds the phone above Ross’s shoulder.)</p><blockquote><p>不！！等等，等等，等等！！哦，请拿着它，这样我就可以听了。（乔伊看着罗斯，把电话举过罗斯的肩膀。）</p></blockquote><p><em>(Chandler escorts Monica down the aisle.)</em></p><blockquote><p><em>（钱德勒陪莫妮卡走下过道。）</em></p></blockquote><p><strong>Chandler Bing:</strong> What we did last night was....</p><blockquote><p>我们昨晚做的是。。。。</p></blockquote><p><strong>Monica Geller:</strong> Stupid.</p><blockquote><p>愚蠢。</p></blockquote><p><strong>Chandler Bing:</strong> Totally crazy stupid. (He nods his head at the people seated.)</p><blockquote><p>完全疯了，笨蛋。（他向坐着的人点头。）</p></blockquote><p><strong>Monica Geller:</strong> What were we thinking?</p><blockquote><p>我们在想什么？</p></blockquote><p><strong>Chandler Bing:</strong> I’m coming over tonight though, right?</p><blockquote><p>不过我今晚要过来，对吗？</p></blockquote><p><strong>Monica Geller:</strong> Oh yeah. Definitely.</p><blockquote><p>哦，是的。肯定</p></blockquote><p><em>(They quickly take their places and Here Comes the Bride Begins to play. Everyone seated looks back. Emily is being escorted up the aisle by her father. She kisses him on the cheek and takes her place by Ross’s side.)</em></p><blockquote><p><em>（他们很快就座，新娘开始玩耍。坐着的每个人都回头看。艾米丽在父亲的陪同下走上过道。她亲吻了他的脸颊，并站在罗斯身边。）</em></p></blockquote><p><strong>Minister:</strong> Friends. Family. We are gathered to celebrate here today the joyous union of Ross and Emily. May the happiness we share with them today be with them always. Now Emily, repeat after me. I, Emily...</p><blockquote><p>朋友们。家庭我们今天在这里欢聚一堂，庆祝罗斯和艾米丽的幸福结合。愿我们今天与他们分享的幸福永远与他们同在。艾米丽，跟我说。一、 艾米丽。。。</p></blockquote><p><strong>Emily:</strong> I, Emily...</p><blockquote><p>我，艾米丽。。。</p></blockquote><p><strong>Minster:</strong> Take thee Ross...</p><blockquote><p>带你去，罗斯。。。</p></blockquote><p><strong>Emily:</strong> Take thee Ross...</p><blockquote><p>带上你，罗斯。。。</p></blockquote><p><strong>Minster:</strong> As my lawfully wedded husband, in sickness and in health, till death parts us.</p><blockquote><p>作为我的合法丈夫，无论疾病还是健康，直到死亡将我们分开。</p></blockquote><p><strong>Emily:</strong> As my lawfully wedded husband, in sickness and in health, until death parts us.</p><blockquote><p>作为我的合法丈夫，无论疾病还是健康，直到死亡将我们分开。</p></blockquote><p><strong>Minster:</strong> Now Ross, repeat after me. I Ross...</p><blockquote><p>罗斯，跟我重复一遍。我是罗斯。。。</p></blockquote><p><strong>Ross Geller:</strong> I Ross...</p><blockquote><p>我是罗斯。。。</p></blockquote><p><strong>Minister:</strong> Take thee, Emily...</p><blockquote><p>带上你，艾米丽。。。</p></blockquote><p><strong>Ross Geller:</strong> Take thee, Rachel...(All his friends have looks of shock on their faces. He realizes what he said. Quickly he says.) Emily. (A slight chuckle.) Emily.</p><blockquote><p>拿你来说，瑞秋…（他所有的朋友脸上都有震惊的表情。他意识到他说的话。他很快说。）艾米丽。（微微一笑）艾米丽。</p></blockquote><p><strong>Minister:</strong> (Looking and feeling awkward. he looks towards Emily.) Uhh...Shall I go on?</p><blockquote><p>（看起来和感觉都很尴尬。他看着艾米丽。）啊……我可以继续吗？</p></blockquote><p><em>(Rachel looks all around as if all the eyes in the chapel were looking at her as the picture fades to black.)</em></p><blockquote><p><em>（瑞秋环顾四周，仿佛教堂里所有的眼睛都在看着她，因为照片逐渐变黑。）</em></p></blockquote><p>Closing Credits</p><blockquote><p>片尾字幕</p></blockquote>`,1134)]])}var s=r(a,[[`render`,o]]);export{i as _pageData,s as default};